const fs = require('fs');
const path = require('path');
const zlib = require('zlib');

// PNG 编码生成器（纯 Node 内置模块，不依赖第三方库）
function createPng(width, height, drawPixelFn) {
  const rowSize = width * 4;
  const rawData = Buffer.alloc((rowSize + 1) * height);

  for (let y = 0; y < height; y++) {
    const rowOffset = y * (rowSize + 1);
    rawData[rowOffset] = 0; // Filter type: None
    for (let x = 0; x < width; x++) {
      const pixelOffset = rowOffset + 1 + x * 4;
      const [r, g, b, a] = drawPixelFn(x, y, width, height);
      rawData[pixelOffset] = r;
      rawData[pixelOffset + 1] = g;
      rawData[pixelOffset + 2] = b;
      rawData[pixelOffset + 3] = a;
    }
  }

  const deflated = zlib.deflateSync(rawData);

  function createChunk(type, data) {
    const len = data.length;
    const buf = Buffer.alloc(12 + len);
    buf.writeUInt32BE(len, 0);
    buf.write(type, 4, 4, 'ascii');
    data.copy(buf, 8);

    // CRC32
    let crc = 0xffffffff;
    for (let i = 4; i < 8 + len; i++) {
      crc = updateCrc(crc, buf[i]);
    }
    crc = (crc ^ 0xffffffff) >>> 0;
    buf.writeUInt32BE(crc, 8 + len);
    return buf;
  }

  // CRC 表计算
  const crcTable = [];
  for (let n = 0; n < 256; n++) {
    let c = n;
    for (let k = 0; k < 8; k++) {
      if (c & 1) c = 0xedb88320 ^ (c >>> 1);
      else c = c >>> 1;
    }
    crcTable[n] = c;
  }
  function updateCrc(crc, byte) {
    return crcTable[(crc ^ byte) & 0xff] ^ (crc >>> 8);
  }

  // IHDR chunk
  const ihdr = Buffer.alloc(13);
  ihdr.writeUInt32BE(width, 0);
  ihdr.writeUInt32BE(height, 4);
  ihdr[8] = 8; // Bit depth: 8
  ihdr[9] = 6; // Color type: RGBA
  ihdr[10] = 0; // Compression: Deflate
  ihdr[11] = 0; // Filter: Adaptive
  ihdr[12] = 0; // Interlace: None

  const signature = Buffer.from([137, 80, 78, 71, 13, 10, 26, 10]);
  const ihdrChunk = createChunk('IHDR', ihdr);
  const idatChunk = createChunk('IDAT', deflated);
  const iendChunk = createChunk('IEND', Buffer.alloc(0));

  return Buffer.concat([signature, ihdrChunk, idatChunk, iendChunk]);
}

// 绘制具有现代化品牌感图标的像素着色函数
function drawIcon(x, y, size) {
  const normX = x / size;
  const normY = y / size;

  // 1. 圆角矩形裁切
  const radius = 0.22;
  const dx = Math.max(0, Math.max(radius - normX, normX - (1 - radius)));
  const dy = Math.max(0, Math.max(radius - normY, normY - (1 - radius)));
  const dist = Math.sqrt(dx * dx + dy * dy);
  if (dist > radius) {
    return [0, 0, 0, 0]; // 透明
  }

  // 2. 现代渐变背景（YouTube 经典红 -> 活力紫罗兰/深靛蓝）
  // (255, 0, 51) -> (100, 40, 220)
  const t = (normX + normY) / 2;
  let r = Math.round(240 * (1 - t) + 80 * t);
  let g = Math.round(40 * (1 - t) + 30 * t);
  let b = Math.round(50 * (1 - t) + 210 * t);
  let a = 255;

  // 3. 内部字幕气泡 / 对话框图形
  // 底部字幕框或播放器卡片
  const inCard = normX >= 0.2 && normX <= 0.8 && normY >= 0.25 && normY <= 0.75;
  if (inCard) {
    // 卡片内白色/浅灰半透明底板
    const cardBg = 255;
    r = Math.round(r * 0.15 + cardBg * 0.85);
    g = Math.round(g * 0.15 + cardBg * 0.85);
    b = Math.round(b * 0.15 + cardBg * 0.85);

    // 绘制两条音波/字幕条（一条代表断句原文，一条代表翻译）
    const line1 = normY >= 0.38 && normY <= 0.46 && normX >= 0.28 && normX <= 0.72;
    const line2 = normY >= 0.54 && normY <= 0.62 && normX >= 0.28 && normX <= 0.62;

    if (line1) {
      // 蓝色/紫色的第一行字幕
      r = 50; g = 100; b = 230;
    } else if (line2) {
      // 红色/金色的第二行翻译字幕
      r = 235; g = 60; b = 60;
    }
  }

  return [r, g, b, a];
}

const iconsDir = path.join(__dirname, 'icons');
[16, 32, 48, 128].forEach(size => {
  const pngBuf = createPng(size, size, (x, y) => drawIcon(x, y, size));
  fs.writeFileSync(path.join(iconsDir, `icon${size}.png`), pngBuf);
  console.log(`Generated icon${size}.png (${size}x${size})`);
});

{
  "compilerOptions": {
    "target": "ESNext",
    "module": "ESNext",
    "moduleResolution": "Bundler",
    "strict": true,
    "esModuleInterop": true,
    "skipLibCheck": true,
    "forceConsistentCasingInFileNames": true,
    "jsx": "preserve",
    "paths": {
      "@/*": ["./*"]
    }
  },
  "include": [
    "entrypoints/**/*",
    "utils/**/*",
    "types/**/*",
    "wxt.config.ts"
  ]
}

import { defineConfig } from 'wxt';

export default defineConfig({
  manifest: {
    name: 'YouTube 自动字幕断句翻译器 (YT Subtitle Segmenter & Translator)',
    description: '针对 YouTube 自动语音生成字幕（ASR）提供智能停顿断句、语义标点重构、双语对齐展示与多源实时翻译（Google / DeepSeek / Gemini / OpenAI）。',
    version: '1.0.0',
    permissions: ['storage'],
    host_permissions: [
      '*://*.youtube.com/*',
      'https://translate.googleapis.com/*',
      'https://api.openai.com/*',
      'https://api.deepseek.com/*',
      'https://generativelanguage.googleapis.com/*'
    ],
    action: {
      default_title: 'YouTube 字幕断句翻译设置'
    }
  }
});

/**
 * YouTube 字幕原始数据格式 (Timedtext JSON3)
 */
export interface YouTubeCaptionTrack {
  baseUrl: string;
  name: { simpleText?: string; runs?: Array<{ text: string }> };
  vssId: string;
  languageCode: string;
  kind?: string; // 'asr' 表示自动生成语音识别字幕
  isTranslatable?: boolean;
}

export interface YouTubePlayerResponse {
  captions?: {
    playerCaptionsTracklistRenderer?: {
      captionTracks?: YouTubeCaptionTrack[];
      translationLanguages?: Array<{
        languageCode: string;
        languageName: { simpleText: string };
      }>;
    };
  };
  videoDetails?: {
    videoId: string;
    title: string;
    author: string;
    lengthSeconds: string;
  };
}

export interface Json3Seg {
  utf8: string;
  tOffsetMs?: number;
  acAsrConf?: number;
}

export interface Json3Event {
  tStartMs: number;
  dDurationMs: number;
  wWinId?: number;
  segs?: Json3Seg[];
  id?: number;
}

export interface Json3CaptionData {
  wireMagic?: string;
  events?: Json3Event[];
}

/**
 * 单词 Token 粒度
 */
export interface CaptionToken {
  text: string;
  start: number; // 毫秒
  end: number;   // 毫秒
  gapToNext: number; // 距离下一个词的毫秒停顿
}

/**
 * 重构后的句子数据结构
 */
export interface SubtitleSentence {
  id: number;
  start: number; // 毫秒
  end: number;   // 毫秒
  text: string;  // 重构断句并修补标点后的完整原文
  rawTokens?: CaptionToken[];
  translation?: string; // 翻译后的译文
  status: 'idle' | 'translating' | 'done' | 'error';
}

/**
 * 扩展配置参数
 */
export interface ExtensionSettings {
  enabled: boolean;
  targetLang: string; // 目标语言，如 'zh-CN', 'zh-TW', 'en', 'ja', 'ko', 'es' 等
  service: 'google' | 'gemini' | 'openai' | 'deepseek';
  apiKey?: string;
  apiBaseUrl?: string; // 大模型自定义端点，如 https://api.deepseek.com/v1
  modelName?: string;  // 如 deepseek-chat, gpt-4o-mini, gemini-1.5-flash 等

  // 断句参数
  pauseThreshold: number; // 停顿切分阈值，默认 450 (ms)
  maxWordsPerSentence: number; // 单句最大单词数，默认 16
  minWordsPerSentence: number; // 单句最小单词数，默认 3
  maxDurationMs: number; // 单句最大持续时间，默认 6500 (ms)
  autoPunctuation: boolean; // 是否智能补齐大小写和标点

  // UI 样式与排版
  displayMode: 'bilingual' | 'translation_only' | 'original_only';
  layoutOrder: 'original_top' | 'translation_top';
  fontSize: number; // px，默认 20
  bgOpacity: number; // 0 ~ 100，默认 75
  offsetY: number; // 垂直偏移百分比，默认 85% (靠近底部)
  autoHideNativeSubtitles: boolean; // 是否自动隐藏 YouTube 默认字幕避免重叠
}

/**
 * 默认配置
 */
export const DEFAULT_SETTINGS: ExtensionSettings = {
  enabled: true,
  targetLang: 'zh-CN',
  service: 'google',
  apiKey: '',
  apiBaseUrl: '',
  modelName: '',
  pauseThreshold: 450,
  maxWordsPerSentence: 16,
  minWordsPerSentence: 3,
  maxDurationMs: 6500,
  autoPunctuation: true,
  displayMode: 'bilingual',
  layoutOrder: 'original_top',
  fontSize: 20,
  bgOpacity: 75,
  offsetY: 82,
  autoHideNativeSubtitles: true
};

/**
 * 消息通信协议
 */
export type ExtensionMessage =
  | { type: 'FETCH_CAPTIONS'; payload: { url: string } }
  | { type: 'TRANSLATE_BATCH'; payload: { texts: string[]; targetLang: string; settings: ExtensionSettings } }
  | { type: 'GET_SETTINGS' }
  | { type: 'SAVE_SETTINGS'; payload: Partial<ExtensionSettings> };

import type {
  Json3CaptionData,
  CaptionToken,
  SubtitleSentence,
  ExtensionSettings
} from '../types';

/**
 * 常见英语简写词列表，避免因句点错误断句
 */
const COMMON_ABBREVIATIONS = new Set([
  'mr.', 'mrs.', 'ms.', 'dr.', 'prof.', 'vs.', 'etc.', 'i.e.', 'e.g.',
  'u.s.', 'u.k.', 'inc.', 'ltd.', 'corp.', 'jr.', 'sr.', 'st.', 'ave.'
]);

/**
 * 常见疑问句起始词
 */
const QUESTION_STARTERS = new Set([
  'what', 'why', 'how', 'who', 'whom', 'whose', 'where', 'when', 'which',
  'is', 'are', 'am', 'was', 'were', 'do', 'does', 'did',
  'can', 'could', 'should', 'would', 'will', 'shall', 'may', 'might',
  'have', 'has', 'had'
]);

/**
 * 强从句连词和转折词（新句常见首词）
 */
const STRONG_CLAUSE_STARTERS = new Set([
  'however', 'therefore', 'moreover', 'furthermore', 'meanwhile',
  'finally', 'secondly', 'thirdly', 'basically', 'actually', 'incidentally',
  'nonetheless', 'nevertheless', 'conversely', 'otherwise'
]);

/**
 * 次级连词
 */
const SECONDARY_CONJUNCTIONS = new Set([
  'and', 'but', 'so', 'because', 'although', 'though', 'while', 'whereas',
  'if', 'unless', 'since', 'as', 'or'
]);

/**
 * 从 YouTube Timedtext JSON3 原始数据解析出单词级别的 Token 列表
 */
export function extractCaptionTokens(captionData: Json3CaptionData): CaptionToken[] {
  const rawTokens: Array<{ text: string; start: number; end?: number }> = [];

  const events = captionData.events || [];

  for (const event of events) {
    if (!event.segs || event.segs.length === 0) {
      continue;
    }

    const eventStart = event.tStartMs;
    const eventDuration = event.dDurationMs;

    for (let i = 0; i < event.segs.length; i++) {
      const seg = event.segs[i];
      const text = seg.utf8 ? seg.utf8.replace(/[\r\n]+/g, ' ').trim() : '';
      if (!text) continue;

      const segOffset = seg.tOffsetMs ?? 0;
      const segStart = eventStart + segOffset;

      // 初步估算单个 seg 结束时间
      let segEnd: number | undefined;
      if (i < event.segs.length - 1 && event.segs[i + 1].tOffsetMs !== undefined) {
        segEnd = eventStart + event.segs[i + 1].tOffsetMs!;
      } else {
        segEnd = eventStart + eventDuration;
      }

      // 保证 segEnd 不早于 segStart
      if (segEnd <= segStart) {
        segEnd = segStart + Math.max(150, text.length * 40);
      }

      rawTokens.push({
        text,
        start: segStart,
        end: segEnd
      });
    }
  }

  // 按起始时间排序
  rawTokens.sort((a, b) => a.start - b.start);

  const tokens: CaptionToken[] = [];
  for (let i = 0; i < rawTokens.length; i++) {
    const cur = rawTokens[i];
    const next = rawTokens[i + 1];

    let end = cur.end ?? (cur.start + 250);
    let gapToNext = 0;

    if (next) {
      if (next.start > end) {
        gapToNext = next.start - end;
      } else {
        // 如果相邻词时间重叠，截断当前词的结束时间，gap 设为 0
        end = Math.min(end, next.start);
        gapToNext = 0;
      }
    } else {
      gapToNext = 999999; // 最后一个词
    }

    tokens.push({
      text: cur.text,
      start: cur.start,
      end: Math.max(cur.start + 50, end),
      gapToNext
    });
  }

  return tokens;
}

/**
 * 判断词尾是否具有断句标点符号
 */
function hasSentenceTerminalPunctuation(word: string): boolean {
  const clean = word.trim().toLowerCase();
  if (COMMON_ABBREVIATIONS.has(clean)) {
    return false;
  }
  return /[.!?。！？]$/.test(clean);
}

/**
 * 智能大小写与句末标点自动修补
 */
function polishSentenceText(tokens: CaptionToken[], autoPunctuation: boolean): string {
  if (tokens.length === 0) return '';

  const rawJoined = tokens.map(t => t.text).join(' ').trim();
  if (!autoPunctuation) {
    return rawJoined;
  }

  // 1. 首字母大写处理
  let polished = rawJoined.charAt(0).toUpperCase() + rawJoined.slice(1);

  // 2. 检查末尾是否已有标点
  if (!/[.!?。！？]$/.test(polished)) {
    // 检查句首是否是疑问词 starter
    const firstWord = tokens[0].text.trim().toLowerCase().replace(/[^a-z]/g, '');
    if (QUESTION_STARTERS.has(firstWord)) {
      polished += '?';
    } else {
      polished += '.';
    }
  }

  return polished;
}

/**
 * 核心断句算法：结合时间停顿、语义语法与长度约束，将连续词流重组为自然流畅的句子
 */
export function segmentCaptionTokens(
  tokens: CaptionToken[],
  settings: Pick<
    ExtensionSettings,
    'pauseThreshold' | 'maxWordsPerSentence' | 'minWordsPerSentence' | 'maxDurationMs' | 'autoPunctuation'
  >
): SubtitleSentence[] {
  if (tokens.length === 0) return [];

  const sentences: SubtitleSentence[] = [];
  let currentGroup: CaptionToken[] = [];
  let sentenceId = 1;

  const {
    pauseThreshold,
    maxWordsPerSentence,
    minWordsPerSentence,
    maxDurationMs,
    autoPunctuation
  } = settings;

  const flushCurrentGroup = () => {
    if (currentGroup.length === 0) return;

    const start = currentGroup[0].start;
    let end = currentGroup[currentGroup.length - 1].end;

    // 确保单句在屏幕上的停留时间不少于 900ms，避免闪烁
    if (end - start < 900) {
      end = start + 900;
    }

    const text = polishSentenceText(currentGroup, autoPunctuation);

    sentences.push({
      id: sentenceId++,
      start,
      end,
      text,
      rawTokens: [...currentGroup],
      status: 'idle'
    });

    currentGroup = [];
  };

  for (let i = 0; i < tokens.length; i++) {
    const token = tokens[i];
    const nextToken = tokens[i + 1];
    currentGroup.push(token);

    // 如果已经是最后一个词，直接输出
    if (!nextToken) {
      flushCurrentGroup();
      break;
    }

    const wordCount = currentGroup.length;
    const currentDuration = token.end - currentGroup[0].start;
    const gap = token.gapToNext;
    const nextWordLower = nextToken.text.trim().toLowerCase().replace(/[^a-z]/g, '');

    let shouldBreak = false;

    // 条件 1: 自身自带明确的句末标点（如 . ! ?），并且满足最小词数要求
    if (hasSentenceTerminalPunctuation(token.text)) {
      shouldBreak = true;
    }
    // 条件 2: 超过时间停顿阈值（说话人呼吸/停顿）且达到最小单句词数
    else if (gap >= pauseThreshold && wordCount >= minWordsPerSentence) {
      shouldBreak = true;
    }
    // 条件 3: 强从句连词起首（如 However, Therefore, Finally）+ 一定的小停顿
    else if (
      STRONG_CLAUSE_STARTERS.has(nextWordLower) &&
      gap >= 220 &&
      wordCount >= minWordsPerSentence
    ) {
      shouldBreak = true;
    }
    // 条件 4: 弱连词（and, but, so, because）+ 中等停顿 + 词数已经稍多
    else if (
      SECONDARY_CONJUNCTIONS.has(nextWordLower) &&
      gap >= Math.max(260, pauseThreshold * 0.65) &&
      wordCount >= 6
    ) {
      shouldBreak = true;
    }
    // 条件 5: 达到了最大词数限制或最大持续时间
    else if (wordCount >= maxWordsPerSentence || currentDuration >= maxDurationMs) {
      // 只要稍微有一点停顿或者在连词处，就可以切断
      if (gap >= 120 || SECONDARY_CONJUNCTIONS.has(nextWordLower) || wordCount >= maxWordsPerSentence + 4) {
        shouldBreak = true;
      }
    }

    if (shouldBreak) {
      flushCurrentGroup();
    }
  }

  return sentences;
}

import type { ExtensionSettings, SubtitleSentence } from '../types';

/**
 * 翻译结果缓存 (key: `${targetLang}:${text}`)
 */
const translationCache = new Map<string, string>();

/**
 * 获取翻译缓存 key
 */
function getCacheKey(targetLang: string, text: string): string {
  return `${targetLang}:${text.trim().toLowerCase()}`;
}

/**
 * 将多句文本使用 Google 网页翻译进行翻译
 */
async function translateWithGoogle(
  texts: string[],
  targetLang: string
): Promise<string[]> {
  if (texts.length === 0) return [];

  // 首先检查缓存
  const results: Array<string | null> = texts.map(t => translationCache.get(getCacheKey(targetLang, t)) ?? null);
  const uncachedIndices: number[] = [];
  const uncachedTexts: string[] = [];

  for (let i = 0; i < texts.length; i++) {
    if (results[i] === null) {
      uncachedIndices.push(i);
      uncachedTexts.push(texts[i]);
    }
  }

  if (uncachedTexts.length === 0) {
    return results as string[];
  }

  // Google Translate 单次请求建议不超过 3000 字符，按批次处理
  const batchSize = 10;
  for (let i = 0; i < uncachedTexts.length; i += batchSize) {
    const chunkTexts = uncachedTexts.slice(i, i + batchSize);
    const chunkIndices = uncachedIndices.slice(i, i + batchSize);

    // 将多句用明确的换行符隔开
    const combinedText = chunkTexts.join('\n');
    const url = `https://translate.googleapis.com/translate_a/single?client=gtx&sl=auto&tl=${encodeURIComponent(
      targetLang
    )}&dt=t&q=${encodeURIComponent(combinedText)}`;

    try {
      const response = await fetch(url);
      if (!response.ok) {
        throw new Error(`Google Translate HTTP error: ${response.status}`);
      }
      const data = await response.json();

      // Google 返回的结构：data[0] 为分段列表，形如 [[translated1, original1], [translated2, original2], ...]
      let fullTranslatedStr = '';
      if (Array.isArray(data) && Array.isArray(data[0])) {
        for (const segment of data[0]) {
          if (segment && segment[0]) {
            fullTranslatedStr += segment[0];
          }
        }
      }

      // 将翻译后的文本按换行切分
      const translatedLines = fullTranslatedStr
        .split('\n')
        .map(l => l.trim())
        .filter(Boolean);

      // 如果切分后的行数与原请求行数一致，直接对应
      if (translatedLines.length === chunkTexts.length) {
        for (let j = 0; j < chunkTexts.length; j++) {
          const trans = translatedLines[j];
          const globalIdx = chunkIndices[j];
          results[globalIdx] = trans;
          translationCache.set(getCacheKey(targetLang, chunkTexts[j]), trans);
        }
      } else {
        // 如果行数不匹配，降级为并发单句翻译
        const fallbackPromises = chunkTexts.map(async (text, subIdx) => {
          const singleUrl = `https://translate.googleapis.com/translate_a/single?client=gtx&sl=auto&tl=${encodeURIComponent(
            targetLang
          )}&dt=t&q=${encodeURIComponent(text)}`;
          try {
            const singleRes = await fetch(singleUrl);
            const singleData = await singleRes.json();
            let singleTrans = '';
            if (Array.isArray(singleData) && Array.isArray(singleData[0])) {
              for (const seg of singleData[0]) {
                if (seg && seg[0]) singleTrans += seg[0];
              }
            }
            const finalTrans = singleTrans.trim() || text;
            const globalIdx = chunkIndices[subIdx];
            results[globalIdx] = finalTrans;
            translationCache.set(getCacheKey(targetLang, text), finalTrans);
          } catch {
            const globalIdx = chunkIndices[subIdx];
            results[globalIdx] = text; // 降级返回原文
          }
        });
        await Promise.all(fallbackPromises);
      }
    } catch (err) {
      console.error('[YT-Sub-Translator] Google translate batch failed:', err);
      // 出错时填回原文或报错
      for (const globalIdx of chunkIndices) {
        if (results[globalIdx] === null) {
          results[globalIdx] = texts[globalIdx];
        }
      }
    }
  }

  return results.map((r, i) => r ?? texts[i]);
}

/**
 * 使用 OpenAI / DeepSeek 等兼容接口进行批量结构化翻译
 */
async function translateWithOpenAICompatible(
  texts: string[],
  targetLang: string,
  settings: ExtensionSettings
): Promise<string[]> {
  const { apiKey, apiBaseUrl, service, modelName } = settings;
  if (!apiKey) {
    throw new Error('未配置 API Key，请在插件设置中填入');
  }

  let baseUrl = apiBaseUrl?.trim();
  if (!baseUrl) {
    if (service === 'deepseek') {
      baseUrl = 'https://api.deepseek.com/v1';
    } else {
      baseUrl = 'https://api.openai.com/v1';
    }
  }
  // 去除末尾的斜杠
  baseUrl = baseUrl.replace(/\/+$/, '');
  const endpoint = `${baseUrl}/chat/completions`;

  const model = modelName?.trim() || (service === 'deepseek' ? 'deepseek-chat' : 'gpt-4o-mini');

  const payloadItems = texts.map((text, id) => ({ id, text }));

  const systemPrompt = `你是一位精通视频双语字幕翻译的资深专家。
任务：将用户提供的多句视频字幕原文翻译为目标语言：${targetLang}。
要求：
1. 语言地道自然，符合影视和口语化表达习惯，简练通顺。
2. 保持上下文连贯，准确处理前后句的代词指代。
3. 必须严格输出 JSON 数组格式，不要包含任何 markdown 解释或代码块标记，结构如下：
[{"id": 0, "translation": "..."}, {"id": 1, "translation": "..."}]`;

  const response = await fetch(endpoint, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      Authorization: `Bearer ${apiKey}`
    },
    body: JSON.stringify({
      model,
      messages: [
        { role: 'system', content: systemPrompt },
        { role: 'user', content: JSON.stringify(payloadItems) }
      ],
      temperature: 0.3
    })
  });

  if (!response.ok) {
    const errText = await response.text();
    throw new Error(`AI 翻译接口请求失败 (${response.status}): ${errText}`);
  }

  const data = await response.json();
  const rawContent = data.choices?.[0]?.message?.content || '';

  // 清洗可能存在的 markdown 代码块包裹 (```json ... ```)
  const cleaned = rawContent.replace(/```(?:json)?/gi, '').replace(/```/g, '').trim();
  const parsed = JSON.parse(cleaned) as Array<{ id: number; translation: string }>;

  const transMap = new Map<number, string>();
  for (const item of parsed) {
    transMap.set(item.id, item.translation);
  }

  return texts.map((t, idx) => {
    const res = transMap.get(idx) || t;
    translationCache.set(getCacheKey(targetLang, t), res);
    return res;
  });
}

/**
 * 使用 Google Gemini 原生 API 进行翻译
 */
async function translateWithGemini(
  texts: string[],
  targetLang: string,
  settings: ExtensionSettings
): Promise<string[]> {
  const { apiKey, modelName } = settings;
  if (!apiKey) {
    throw new Error('未配置 Gemini API Key，请在插件设置中填入');
  }

  const model = modelName?.trim() || 'gemini-1.5-flash';
  const endpoint = `https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent?key=${apiKey}`;

  const payloadItems = texts.map((text, id) => ({ id, text }));

  const prompt = `你是一位专业视频字幕翻译家。请将以下按顺序给出的英文视频断句翻译成目标语言：${targetLang}。
保持口语自然、用词地道。
请直接返回 JSON 格式，不要使用任何多余文字或 markdown：
[{"id": 0, "translation": "..."}, ...]

待翻译内容：
${JSON.stringify(payloadItems)}`;

  const response = await fetch(endpoint, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      contents: [{ parts: [{ text: prompt }] }],
      generationConfig: {
        responseMimeType: 'application/json'
      }
    })
  });

  if (!response.ok) {
    const errText = await response.text();
    throw new Error(`Gemini API 错误 (${response.status}): ${errText}`);
  }

  const data = await response.json();
  const rawText = data.candidates?.[0]?.content?.parts?.[0]?.text || '';
  const parsed = JSON.parse(rawText) as Array<{ id: number; translation: string }>;

  const transMap = new Map<number, string>();
  for (const item of parsed) {
    transMap.set(item.id, item.translation);
  }

  return texts.map((t, idx) => {
    const res = transMap.get(idx) || t;
    translationCache.set(getCacheKey(targetLang, t), res);
    return res;
  });
}

/**
 * 统一翻译分发入口
 */
export async function translateSentenceBatch(
  texts: string[],
  targetLang: string,
  settings: ExtensionSettings
): Promise<string[]> {
  if (texts.length === 0) return [];

  const service = settings.service || 'google';

  try {
    switch (service) {
      case 'deepseek':
      case 'openai':
        return await translateWithOpenAICompatible(texts, targetLang, settings);
      case 'gemini':
        return await translateWithGemini(texts, targetLang, settings);
      case 'google':
      default:
        return await translateWithGoogle(texts, targetLang);
    }
  } catch (error) {
    console.warn(`[YT-Sub-Translator] ${service} 翻译异常，降级回 Google 免费翻译:`, error);
    // 若 AI 翻译报错，自动降级为 Google 免费翻译，保证字幕始终可用
    return await translateWithGoogle(texts, targetLang);
  }
}

import { DEFAULT_SETTINGS, type ExtensionSettings } from '../types';

const STORAGE_KEY = 'yt_sub_translator_settings';

/**
 * 获取当前用户配置
 */
export async function getStoredSettings(): Promise<ExtensionSettings> {
  return new Promise((resolve) => {
    if (typeof chrome === 'undefined' || !chrome.storage) {
      resolve({ ...DEFAULT_SETTINGS });
      return;
    }

    chrome.storage.sync.get([STORAGE_KEY], (result) => {
      if (chrome.runtime.lastError) {
        // 如果 sync 不可用，降级到 local
        chrome.storage.local.get([STORAGE_KEY], (localRes) => {
          resolve({ ...DEFAULT_SETTINGS, ...(localRes[STORAGE_KEY] || {}) });
        });
        return;
      }
      resolve({ ...DEFAULT_SETTINGS, ...(result[STORAGE_KEY] || {}) });
    });
  });
}

/**
 * 保存用户配置
 */
export async function saveStoredSettings(newSettings: Partial<ExtensionSettings>): Promise<ExtensionSettings> {
  const current = await getStoredSettings();
  const updated: ExtensionSettings = { ...current, ...newSettings };

  return new Promise((resolve) => {
    if (typeof chrome === 'undefined' || !chrome.storage) {
      resolve(updated);
      return;
    }

    chrome.storage.sync.set({ [STORAGE_KEY]: updated }, () => {
      if (chrome.runtime.lastError) {
        chrome.storage.local.set({ [STORAGE_KEY]: updated }, () => {
          resolve(updated);
        });
        return;
      }
      resolve(updated);
    });
  });
}

import { defineBackground } from 'wxt/sandbox';
import type { ExtensionMessage } from '../types';
import { translateSentenceBatch } from '../utils/translator';
import { getStoredSettings, saveStoredSettings } from '../utils/storage';

export default defineBackground(() => {
  console.log('[YT-Sub-Translator] Background service worker initialized.');

  // 同步注册消息监听器 (svc-register-listeners-synchronously)
  chrome.runtime.onMessage.addListener((message: ExtensionMessage, _sender, sendResponse) => {
    if (!message || !message.type) {
      return false;
    }

    switch (message.type) {
      case 'FETCH_CAPTIONS': {
        const { url } = message.payload;
        // 在 background 中 fetch 字幕 json3 数据，彻底绕过网页端跨域与 CSP 限制
        fetch(url)
          .then((res) => {
            if (!res.ok) {
              throw new Error(`Failed to fetch captions: ${res.status}`);
            }
            return res.json();
          })
          .then((data) => {
            sendResponse({ success: true, data });
          })
          .catch((err) => {
            console.error('[YT-Sub-Translator] Fetch captions error:', err);
            sendResponse({ success: false, error: err.message || 'Fetch failed' });
          });
        return true; // 表示异步响应
      }

      case 'TRANSLATE_BATCH': {
        const { texts, targetLang, settings } = message.payload;
        translateSentenceBatch(texts, targetLang, settings)
          .then((translations) => {
            sendResponse({ success: true, translations });
          })
          .catch((err) => {
            console.error('[YT-Sub-Translator] Translation batch error:', err);
            sendResponse({ success: false, error: err.message || 'Translation failed' });
          });
        return true; // 异步响应
      }

      case 'GET_SETTINGS': {
        getStoredSettings()
          .then((settings) => {
            sendResponse({ success: true, settings });
          })
          .catch((err) => {
            sendResponse({ success: false, error: err.message });
          });
        return true;
      }

      case 'SAVE_SETTINGS': {
        saveStoredSettings(message.payload)
          .then((updated) => {
            // 向所有活动 tab 广播配置更新事件
            chrome.tabs.query({ url: '*://*.youtube.com/*' }, (tabs) => {
              for (const tab of tabs) {
                if (tab.id) {
                  chrome.tabs.sendMessage(tab.id, {
                    type: 'SETTINGS_UPDATED',
                    settings: updated
                  }).catch(() => {
                    // 忽略无响应标签页
                  });
                }
              }
            });
            sendResponse({ success: true, settings: updated });
          })
          .catch((err) => {
            sendResponse({ success: false, error: err.message });
          });
        return true;
      }

      default:
        return false;
    }
  });
});

/**
 * 运行在 YouTube 页面主环境 (MAIN world) 的辅助脚本
 * 用于访问 YouTube 播放器实例及其内部 API
 */

export const INJECTED_BRIDGE_CODE = `
(function() {
  if (window.__YT_SUB_TRANSLATOR_BRIDGE_INJECTED__) return;
  window.__YT_SUB_TRANSLATOR_BRIDGE_INJECTED__ = true;

  function getPlayer() {
    return document.getElementById('movie_player') || document.querySelector('.html5-video-player');
  }

  function getCaptionTracks() {
    const player = getPlayer();
    let tracks = null;

    if (player && typeof player.getCaptionTrackList === 'function') {
      try {
        tracks = player.getCaptionTrackList();
      } catch (e) {}
    }

    if (!tracks || tracks.length === 0) {
      const response = (player && typeof player.getPlayerResponse === 'function') 
        ? player.getPlayerResponse() 
        : window.ytInitialPlayerResponse;
      tracks = response?.captions?.playerCaptionsTracklistRenderer?.captionTracks || null;
    }

    return tracks;
  }

  function broadcastTracks(reason) {
    const tracks = getCaptionTracks();
    const player = getPlayer();
    const videoData = player?.getVideoData?.() || null;

    window.postMessage({
      source: 'YT_SUB_TRANSLATOR_MAIN',
      type: 'CAPTION_TRACKS_FOUND',
      tracks: tracks || [],
      videoData: videoData,
      reason: reason || 'poll'
    }, '*');
  }

  // 监听来自 Content Script 的指令
  window.addEventListener('message', function(event) {
    if (event.data && event.data.source === 'YT_SUB_TRANSLATOR_CONTENT') {
      if (event.data.action === 'REQUEST_TRACKS') {
        broadcastTracks('request');
      } else if (event.data.action === 'SEEK_TO') {
        const player = getPlayer();
        if (player && typeof player.seekTo === 'function') {
          player.seekTo(event.data.seconds, true);
        }
      }
    }
  });

  // 监听 YouTube SPA 路由与播放器变动事件
  window.addEventListener('yt-navigate-finish', function() {
    setTimeout(function() { broadcastTracks('yt-navigate-finish'); }, 800);
    setTimeout(function() { broadcastTracks('yt-navigate-finish-delayed'); }, 2000);
  });

  // 周期性轮询检测播放器就绪 (最多轮询数次)
  let attempts = 0;
  const interval = setInterval(function() {
    attempts++;
    const tracks = getCaptionTracks();
    if (tracks && tracks.length > 0) {
      broadcastTracks('initial_ready');
      clearInterval(interval);
    } else if (attempts > 15) {
      clearInterval(interval);
    }
  }, 1000);

  // 首次广播
  setTimeout(function() { broadcastTracks('init'); }, 500);
})();
`;

import type { SubtitleSentence, ExtensionSettings } from '../../types';

export class SubtitleOverlay {
  private host: HTMLElement | null = null;
  private shadow: ShadowRoot | null = null;
  private containerEl: HTMLElement | null = null;
  private origEl: HTMLElement | null = null;
  private transEl: HTMLElement | null = null;
  private drawerEl: HTMLElement | null = null;
  private drawerListEl: HTMLElement | null = null;
  private searchInputEl: HTMLInputElement | null = null;

  private currentSentence: SubtitleSentence | null = null;
  private allSentences: SubtitleSentence[] = [];
  private settings: ExtensionSettings;
  private isVisible: boolean = true;
  private isDrawerOpen: boolean = false;
  private onSeekCallback?: (seconds: number) => void;
  private onSettingsChangeCallback?: (newSettings: Partial<ExtensionSettings>) => void;

  constructor(
    settings: ExtensionSettings,
    callbacks?: {
      onSeek?: (seconds: number) => void;
      onSettingsChange?: (newSettings: Partial<ExtensionSettings>) => void;
    }
  ) {
    this.settings = settings;
    this.onSeekCallback = callbacks?.onSeek;
    this.onSettingsChangeCallback = callbacks?.onSettingsChange;
  }

  /**
   * 挂载到 YouTube 播放器容器
   */
  public mount(playerContainer: HTMLElement) {
    this.destroy();

    this.host = document.createElement('div');
    this.host.id = 'yt-sub-translator-host';
    this.host.style.position = 'absolute';
    this.host.style.top = '0';
    this.host.style.left = '0';
    this.host.style.width = '100%';
    this.host.style.height = '100%';
    this.host.style.pointerEvents = 'none';
    this.host.style.zIndex = '60';

    this.shadow = this.host.attachShadow({ mode: 'open' });
    this.shadow.innerHTML = this.renderTemplate();

    this.containerEl = this.shadow.querySelector('.subtitle-box');
    this.origEl = this.shadow.querySelector('.original-text');
    this.transEl = this.shadow.querySelector('.translated-text');
    this.drawerEl = this.shadow.querySelector('.transcript-drawer');
    this.drawerListEl = this.shadow.querySelector('.drawer-sentences-list');
    this.searchInputEl = this.shadow.querySelector('.drawer-search-input');

    this.bindEvents();
    this.applyStyles();

    playerContainer.appendChild(this.host);
  }

  /**
   * 销毁挂载
   */
  public destroy() {
    if (this.host && this.host.parentElement) {
      this.host.parentElement.removeChild(this.host);
    }
    this.host = null;
    this.shadow = null;
    this.currentSentence = null;
  }

  /**
   * 更新扩展配置
   */
  public updateSettings(newSettings: ExtensionSettings) {
    this.settings = newSettings;
    this.applyStyles();
    if (this.currentSentence) {
      this.renderCurrentSentence(this.currentSentence);
    }
    this.renderDrawerList();
  }

  /**
   * 设置全部句子数据
   */
  public setSentences(sentences: SubtitleSentence[]) {
    this.allSentences = sentences;
    this.renderDrawerList();
  }

  /**
   * 根据当前播放时间毫秒数，高亮显示对应断句
   */
  public onTimeUpdate(currentTimeMs: number) {
    if (!this.isVisible || !this.settings.enabled || this.allSentences.length === 0) {
      this.clearCurrentDisplay();
      return;
    }

    // 查找当前时间落在哪个句子区间
    const matched = this.allSentences.find(
      (s) => currentTimeMs >= s.start && currentTimeMs <= s.end
    );

    if (matched) {
      if (this.currentSentence?.id !== matched.id) {
        this.currentSentence = matched;
        this.renderCurrentSentence(matched);
        this.highlightDrawerItem(matched.id);
      }
    } else {
      // 检查是否刚好在句子结束后的微小间隙，如果相差小于 400ms，保持平滑显示，避免闪烁
      if (this.currentSentence && currentTimeMs - this.currentSentence.end > 450) {
        this.clearCurrentDisplay();
      }
    }
  }

  /**
   * 渲染当前句子内容
   */
  private renderCurrentSentence(sentence: SubtitleSentence) {
    if (!this.containerEl || !this.origEl || !this.transEl) return;

    const { displayMode, layoutOrder } = this.settings;

    this.origEl.textContent = sentence.text;
    this.transEl.textContent = sentence.translation || (sentence.status === 'translating' ? '翻译中...' : '');

    // 显示模式控制
    if (displayMode === 'translation_only') {
      this.origEl.style.display = 'none';
      this.transEl.style.display = 'block';
    } else if (displayMode === 'original_only') {
      this.origEl.style.display = 'block';
      this.transEl.style.display = 'none';
    } else {
      this.origEl.style.display = 'block';
      this.transEl.style.display = 'block';
    }

    // 排版上下顺序
    if (layoutOrder === 'translation_top') {
      this.containerEl.style.flexDirection = 'column-reverse';
    } else {
      this.containerEl.style.flexDirection = 'column';
    }

    this.containerEl.classList.add('active');
  }

  /**
   * 清除当前显示的字幕
   */
  private clearCurrentDisplay() {
    this.currentSentence = null;
    if (this.containerEl) {
      this.containerEl.classList.remove('active');
    }
  }

  /**
   * 切换全局显示/隐藏
   */
  public toggleVisibility() {
    this.isVisible = !this.isVisible;
    if (this.containerEl) {
      this.containerEl.style.display = this.isVisible ? 'flex' : 'none';
    }
  }

  /**
   * 打开/关闭全文剧本侧边抽屉
   */
  public toggleDrawer() {
    this.isDrawerOpen = !this.isDrawerOpen;
    if (this.drawerEl) {
      if (this.isDrawerOpen) {
        this.drawerEl.classList.add('open');
        this.renderDrawerList();
        if (this.currentSentence) {
          this.highlightDrawerItem(this.currentSentence.id, true);
        }
      } else {
        this.drawerEl.classList.remove('open');
      }
    }
  }

  /**
   * 渲染剧本抽屉列表
   */
  private renderDrawerList() {
    if (!this.drawerListEl) return;

    const filterText = (this.searchInputEl?.value || '').trim().toLowerCase();
    const filtered = this.allSentences.filter((s) => {
      if (!filterText) return true;
      return (
        s.text.toLowerCase().includes(filterText) ||
        (s.translation && s.translation.toLowerCase().includes(filterText))
      );
    });

    if (filtered.length === 0) {
      this.drawerListEl.innerHTML = `
        <div class="empty-state">
          ${this.allSentences.length === 0 ? '正在检测与加载字幕轨道...' : '未找到匹配的字幕'}
        </div>
      `;
      return;
    }

    this.drawerListEl.innerHTML = '';
    const fragment = document.createDocumentFragment();

    for (const s of filtered) {
      const itemEl = document.createElement('div');
      itemEl.className = `drawer-item ${this.currentSentence?.id === s.id ? 'current' : ''}`;
      itemEl.dataset.id = String(s.id);
      itemEl.dataset.start = String(s.start / 1000);

      const timeStr = this.formatTime(s.start);

      itemEl.innerHTML = `
        <div class="item-time">${timeStr}</div>
        <div class="item-content">
          <div class="item-original">${this.escapeHtml(s.text)}</div>
          <div class="item-translation">${this.escapeHtml(s.translation || '（待翻译）')}</div>
        </div>
      `;

      itemEl.addEventListener('click', () => {
        if (this.onSeekCallback) {
          this.onSeekCallback(s.start / 1000);
        }
      });

      fragment.appendChild(itemEl);
    }

    this.drawerListEl.appendChild(fragment);
  }

  /**
   * 高亮剧本抽屉中的对应项
   */
  private highlightDrawerItem(sentenceId: number, autoScroll = false) {
    if (!this.drawerListEl) return;

    const prev = this.drawerListEl.querySelector('.drawer-item.current');
    if (prev) prev.classList.remove('current');

    const curr = this.drawerListEl.querySelector(`[data-id="${sentenceId}"]`) as HTMLElement;
    if (curr) {
      curr.classList.add('current');
      if (this.isDrawerOpen || autoScroll) {
        curr.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
      }
    }
  }

  /**
   * 应用位置、字号、透明度样式
   */
  private applyStyles() {
    if (!this.containerEl || !this.origEl || !this.transEl) return;

    const { fontSize, bgOpacity, offsetY } = this.settings;

    this.containerEl.style.top = `${offsetY}%`;
    this.containerEl.style.backgroundColor = `rgba(15, 23, 42, ${bgOpacity / 100})`;

    this.origEl.style.fontSize = `${fontSize * 0.85}px`;
    this.transEl.style.fontSize = `${fontSize}px`;
  }

  /**
   * 绑定各种交互事件（拖拽、复制、搜索、导出）
   */
  private bindEvents() {
    if (!this.shadow || !this.containerEl) return;

    // 1. 拖拽垂直位置功能
    const handleEl = this.shadow.querySelector('.drag-handle') as HTMLElement;
    let isDragging = false;
    let startY = 0;
    let startTopPercent = this.settings.offsetY;

    if (handleEl) {
      handleEl.addEventListener('mousedown', (e) => {
        isDragging = true;
        startY = e.clientY;
        startTopPercent = parseFloat(this.containerEl!.style.top) || this.settings.offsetY;
        document.body.style.userSelect = 'none';
        e.preventDefault();
        e.stopPropagation();
      });

      window.addEventListener('mousemove', (e) => {
        if (!isDragging || !this.host) return;
        const rect = this.host.getBoundingClientRect();
        if (rect.height <= 0) return;

        const deltaY = e.clientY - startY;
        const deltaPercent = (deltaY / rect.height) * 100;
        let newPercent = Math.max(10, Math.min(92, startTopPercent + deltaPercent));

        this.containerEl!.style.top = `${newPercent}%`;
      });

      window.addEventListener('mouseup', () => {
        if (isDragging) {
          isDragging = false;
          document.body.style.userSelect = '';
          const currentPercent = Math.round(parseFloat(this.containerEl!.style.top));
          this.settings.offsetY = currentPercent;
          if (this.onSettingsChangeCallback) {
            this.onSettingsChangeCallback({ offsetY: currentPercent });
          }
        }
      });
    }

    // 2. 抽屉开关按钮
    const drawerToggleBtn = this.shadow.querySelector('.btn-drawer');
    drawerToggleBtn?.addEventListener('click', (e) => {
      e.stopPropagation();
      this.toggleDrawer();
    });

    const closeDrawerBtn = this.shadow.querySelector('.drawer-close');
    closeDrawerBtn?.addEventListener('click', (e) => {
      e.stopPropagation();
      this.toggleDrawer();
    });

    // 3. 复制按钮
    const copyBtn = this.shadow.querySelector('.btn-copy');
    copyBtn?.addEventListener('click', (e) => {
      e.stopPropagation();
      if (this.currentSentence) {
        const textToCopy = `${this.currentSentence.text}\n${this.currentSentence.translation || ''}`.trim();
        navigator.clipboard.writeText(textToCopy).then(() => {
          this.showToast('已复制当前句子');
        });
      }
    });

    // 4. 隐藏/显示快捷按钮
    const toggleBtn = this.shadow.querySelector('.btn-hide');
    toggleBtn?.addEventListener('click', (e) => {
      e.stopPropagation();
      this.toggleVisibility();
    });

    // 5. 剧本搜索框
    this.searchInputEl?.addEventListener('input', () => {
      this.renderDrawerList();
    });

    // 6. 导出 SRT / TXT
    const exportSrtBtn = this.shadow.querySelector('.btn-export-srt');
    exportSrtBtn?.addEventListener('click', (e) => {
      e.stopPropagation();
      this.exportSRT();
    });

    const exportTxtBtn = this.shadow.querySelector('.btn-export-txt');
    exportTxtBtn?.addEventListener('click', (e) => {
      e.stopPropagation();
      this.exportTXT();
    });
  }

  /**
   * 导出为双语 SRT 字幕文件
   */
  private exportSRT() {
    if (this.allSentences.length === 0) {
      this.showToast('暂无字幕可导出');
      return;
    }

    let srt = '';
    this.allSentences.forEach((s, idx) => {
      srt += `${idx + 1}\n`;
      srt += `${this.formatSrtTime(s.start)} --> ${this.formatSrtTime(s.end)}\n`;
      srt += `${s.text}\n`;
      if (s.translation) {
        srt += `${s.translation}\n`;
      }
      srt += '\n';
    });

    this.downloadFile(srt, 'youtube-subtitles.srt', 'text/plain;charset=utf-8');
  }

  /**
   * 导出为纯文本 TXT
   */
  private exportTXT() {
    if (this.allSentences.length === 0) {
      this.showToast('暂无字幕可导出');
      return;
    }

    let txt = '';
    this.allSentences.forEach((s) => {
      const timeStr = this.formatTime(s.start);
      txt += `[${timeStr}] ${s.text}\n`;
      if (s.translation) {
        txt += `       ${s.translation}\n`;
      }
      txt += '\n';
    });

    this.downloadFile(txt, 'youtube-subtitles.txt', 'text/plain;charset=utf-8');
  }

  private downloadFile(content: string, filename: string, mime: string) {
    const blob = new Blob([content], { type: mime });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = filename;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
    this.showToast(`已导出 ${filename}`);
  }

  private showToast(msg: string) {
    if (!this.shadow) return;
    const toast = document.createElement('div');
    toast.className = 'toast-notification';
    toast.textContent = msg;
    this.shadow.appendChild(toast);
    setTimeout(() => {
      toast.classList.add('fade-out');
      setTimeout(() => toast.remove(), 400);
    }, 1500);
  }

  private formatTime(ms: number): string {
    const totalSec = Math.floor(ms / 1000);
    const m = Math.floor(totalSec / 60);
    const s = totalSec % 60;
    return `${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}`;
  }

  private formatSrtTime(ms: number): string {
    const totalSec = Math.floor(ms / 1000);
    const h = Math.floor(totalSec / 3600);
    const m = Math.floor((totalSec % 3600) / 60);
    const s = totalSec % 60;
    const millis = ms % 1000;
    return `${String(h).padStart(2, '0')}:${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')},${String(
      millis
    ).padStart(3, '0')}`;
  }

  private escapeHtml(str: string): string {
    return str
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#039;');
  }

