import { defineContentScript } from 'wxt/sandbox';
import type {
  YouTubeCaptionTrack,
  SubtitleSentence,
  ExtensionSettings,
  Json3CaptionData
} from '../../types';
import { getStoredSettings } from '../../utils/storage';
import { extractCaptionTokens, segmentCaptionTokens } from '../../utils/segmenter';
import { INJECTED_BRIDGE_CODE } from './bridge';
import { SubtitleOverlay } from './overlay';

export default defineContentScript({
  matches: ['*://*.youtube.com/*'],
  runAt: 'document_idle',
  main(ctx) {
    console.log('[YT-Sub-Translator] Content script loaded on YouTube.');

    let settings: ExtensionSettings;
    let overlay: SubtitleOverlay | null = null;
    let videoElement: HTMLVideoElement | null = null;
    let currentVideoId: string = '';
    let currentSentences: SubtitleSentence[] = [];
    let isTranslating = false;
    let nativeSubtitleStyleEl: HTMLStyleElement | null = null;

    // 1. 注入主页面桥接脚本 (MAIN world bridge)
    injectBridgeScript();

    // 2. 初始化配置
    getStoredSettings().then((s) => {
      settings = s;
      updateNativeSubtitleVisibility();
      initPlayerObserver();
    });

    // 监听来自 Background 的配置更新通知
    chrome.runtime.onMessage.addListener((message) => {
      if (message.type === 'SETTINGS_UPDATED') {
        const prevLang = settings?.targetLang;
        const prevPause = settings?.pauseThreshold;
        const prevMaxWords = settings?.maxWordsPerSentence;
        settings = message.settings;

        updateNativeSubtitleVisibility();
        if (overlay) {
          overlay.updateSettings(settings);
        }

        // 如果断句参数修改了，重新执行断句并刷新
        if (
          lastCaptionData &&
          (prevPause !== settings.pauseThreshold || prevMaxWords !== settings.maxWordsPerSentence)
        ) {
          reSegmentAndReload(lastCaptionData);
        } else if (prevLang !== settings.targetLang) {
          // 如果目标语言变了，清空翻译缓存并重新批量翻译
          reTranslateAll();
        }
      }
    });

    /**
     * 注入通信脚本到网页主上下文
     */
    function injectBridgeScript() {
      const script = document.createElement('script');
      script.textContent = INJECTED_BRIDGE_CODE;
      (document.head || document.documentElement).appendChild(script);
      script.remove();
    }

    /**
     * 控制 YouTube 原生字幕是否自动隐藏
     */
    function updateNativeSubtitleVisibility() {
      if (!nativeSubtitleStyleEl) {
        nativeSubtitleStyleEl = document.createElement('style');
        nativeSubtitleStyleEl.id = 'yt-sub-translator-native-sub-hider';
        document.head.appendChild(nativeSubtitleStyleEl);
      }

      if (settings?.enabled && settings?.autoHideNativeSubtitles) {
        nativeSubtitleStyleEl.textContent = `
          .ytp-caption-window-container {
            opacity: 0 !important;
            pointer-events: none !important;
          }
        `;
      } else {
        nativeSubtitleStyleEl.textContent = '';
      }
    }

    /**
     * 监听播放器创建并初始化 Overlay
     */
    function initPlayerObserver() {
      setupPlayerAndOverlay();

      // 定期或在 DOM 变动时检查播放器
      const observer = new MutationObserver(() => {
        const player = document.getElementById('movie_player') as HTMLElement;
        const video = document.querySelector('video') as HTMLVideoElement;
        if (player && video && (!overlay || video !== videoElement)) {
          setupPlayerAndOverlay();
        }
      });

      observer.observe(document.body, { childList: true, subtree: true });

      // 请求桥接脚本发送字幕轨道
      window.postMessage({ source: 'YT_SUB_TRANSLATOR_CONTENT', action: 'REQUEST_TRACKS' }, '*');
    }

    /**
     * 绑定播放器与 Overlay
     */
    function setupPlayerAndOverlay() {
      const player = document.getElementById('movie_player') as HTMLElement;
      const video = document.querySelector('video') as HTMLVideoElement;

      if (!player || !video) return;

      videoElement = video;

      if (!overlay) {
        overlay = new SubtitleOverlay(settings, {
          onSeek: (seconds) => {
            window.postMessage(
              { source: 'YT_SUB_TRANSLATOR_CONTENT', action: 'SEEK_TO', seconds },
              '*'
            );
          },
          onSettingsChange: (newSettings) => {
            chrome.runtime.sendMessage({ type: 'SAVE_SETTINGS', payload: newSettings });
          }
        });
      }

      overlay.mount(player);

      // 绑定视频时间更新事件
      videoElement.removeEventListener('timeupdate', handleTimeUpdate);
      videoElement.addEventListener('timeupdate', handleTimeUpdate);
    }

    function handleTimeUpdate() {
      if (!videoElement || !overlay) return;
      const currentTimeMs = videoElement.currentTime * 1000;
      overlay.onTimeUpdate(currentTimeMs);

      // 检查是否需要按需触发后续句子的预翻译
      triggerPreTranslationIfNeeded(currentTimeMs);
    }

    /**
     * 接收来自 MAIN world 桥接脚本的消息
     */
    let lastCaptionData: Json3CaptionData | null = null;
    let currentLoadingTrackUrl: string = '';

    window.addEventListener('message', (event) => {
      if (!event.data || event.data.source !== 'YT_SUB_TRANSLATOR_MAIN') return;

      if (event.data.type === 'CAPTION_TRACKS_FOUND') {
        const { tracks, videoData } = event.data;
        const newVid = videoData?.video_id || new URLSearchParams(window.location.search).get('v') || '';

        if (newVid && newVid !== currentVideoId) {
          currentVideoId = newVid;
          currentSentences = [];
          lastCaptionData = null;
          if (overlay) {
            overlay.setSentences([]);
          }
        }

        if (tracks && tracks.length > 0) {
          handleCaptionTracks(tracks);
        }
      }
    });

    /**
     * 选择最适字幕轨道并加载
     */
    function handleCaptionTracks(tracks: YouTubeCaptionTrack[]) {
      // 优先寻找自动生成字幕 (kind === 'asr')，如果用户需要对自动字幕断句
      let selectedTrack = tracks.find((t) => t.kind === 'asr');

      // 如果没有自动字幕，选择英文或其他原生音轨
      if (!selectedTrack) {
        selectedTrack = tracks.find((t) => t.languageCode === 'en') || tracks[0];
      }

      if (!selectedTrack || !selectedTrack.baseUrl) {
        return;
      }

      let fetchUrl = selectedTrack.baseUrl;
      if (!fetchUrl.includes('fmt=')) {
        fetchUrl += '&fmt=json3';
      }

      if (fetchUrl === currentLoadingTrackUrl && currentSentences.length > 0) {
        return; // 已经加载过此轨
      }

      currentLoadingTrackUrl = fetchUrl;
      console.log('[YT-Sub-Translator] Loading caption track:', selectedTrack);

      // 请求后台抓取 json3 字幕
      chrome.runtime.sendMessage(
        { type: 'FETCH_CAPTIONS', payload: { url: fetchUrl } },
        (response) => {
          if (response && response.success && response.data) {
            lastCaptionData = response.data;
            processCaptionData(response.data);
          } else {
            console.error('[YT-Sub-Translator] Failed to fetch caption track:', response?.error);
          }
        }
      );
    }

    /**
     * 处理字幕数据：分词、停顿智能断句、标点修补
     */
    function processCaptionData(data: Json3CaptionData) {
      const tokens = extractCaptionTokens(data);
      console.log(`[YT-Sub-Translator] Extracted ${tokens.length} raw caption tokens.`);

      const sentences = segmentCaptionTokens(tokens, settings);
      console.log(`[YT-Sub-Translator] Segmented into ${sentences.length} fluent sentences.`);

      currentSentences = sentences;
      if (overlay) {
        overlay.setSentences(currentSentences);
      }

      // 启动预翻译
      startPreTranslationPipeline();
    }

    /**
     * 重新根据新设置断句
     */
    function reSegmentAndReload(data: Json3CaptionData) {
      const tokens = extractCaptionTokens(data);
      const sentences = segmentCaptionTokens(tokens, settings);
      currentSentences = sentences;
      if (overlay) {
        overlay.setSentences(currentSentences);
      }
      startPreTranslationPipeline();
    }

    /**
     * 重新翻译所有已断句
     */
    function reTranslateAll() {
      for (const s of currentSentences) {
        s.translation = undefined;
        s.status = 'idle';
      }
      startPreTranslationPipeline();
    }

    /**
     * 启动预翻译管道：先翻译前 15 句，后续随着播放滑动窗口分批预翻译
     */
    function startPreTranslationPipeline() {
      if (currentSentences.length === 0) return;

      // 首先翻译最开始的 15 句
      translateSentenceRange(0, Math.min(15, currentSentences.length));
    }

    /**
     * 随着播放进度按需预翻译未来 45 秒内的句子
     */
    function triggerPreTranslationIfNeeded(currentTimeMs: number) {
      if (isTranslating || currentSentences.length === 0) return;

      const lookaheadMs = 45000; // 预读未来 45 秒
      const windowEndMs = currentTimeMs + lookaheadMs;

      // 找到未来时间窗内尚未翻译的第一组句子
      let firstUntranslatedIdx = -1;
      let count = 0;

      for (let i = 0; i < currentSentences.length; i++) {
        const s = currentSentences[i];
        if (s.start > windowEndMs) break;

        if (s.start >= currentTimeMs - 5000 && !s.translation && s.status === 'idle') {
          if (firstUntranslatedIdx === -1) {
            firstUntranslatedIdx = i;
          }
          count++;
          if (count >= 12) break; // 每批最多 12 句
        }
      }

      if (firstUntranslatedIdx !== -1 && count > 0) {
        translateSentenceRange(firstUntranslatedIdx, firstUntranslatedIdx + count);
      }
    }

    /**
     * 批量翻译特定索引区间的句子
     */
    function translateSentenceRange(startIdx: number, endIdx: number) {
      if (isTranslating) return;

      const targets = currentSentences.slice(startIdx, endIdx).filter((s) => !s.translation && s.status === 'idle');
      if (targets.length === 0) return;

      isTranslating = true;
      for (const t of targets) {
        t.status = 'translating';
      }

      const texts = targets.map((t) => t.text);

      chrome.runtime.sendMessage(
        {
          type: 'TRANSLATE_BATCH',
          payload: {
            texts,
            targetLang: settings.targetLang,
            settings
          }
        },
        (res) => {
          isTranslating = false;
          if (res && res.success && Array.isArray(res.translations)) {
            for (let i = 0; i < targets.length; i++) {
              targets[i].translation = res.translations[i] || targets[i].text;
              targets[i].status = 'done';
            }
          } else {
            console.warn('[YT-Sub-Translator] Batch translation failed:', res?.error);
            for (const t of targets) {
              t.status = 'error';
            }
          }

          if (overlay) {
            overlay.setSentences(currentSentences);
          }
        }
      );
    }

    // 快捷键支持：Alt + V 快速切换字幕显隐
    window.addEventListener('keydown', (e) => {
      if (e.altKey && (e.key === 'v' || e.key === 'V')) {
        if (overlay) {
          overlay.toggleVisibility();
        }
      }
    });
  }
});

:root {
  --bg-primary: #0f172a;
  --bg-secondary: #1e293b;
  --bg-card: rgba(30, 41, 59, 0.7);
