import { extractCaptionTokens, segmentCaptionTokens } from '../utils/segmenter.ts';
import { DEFAULT_SETTINGS } from '../types/index.ts';

// 构造一个模拟 YouTube 自动字幕 (JSON3)
const mockJson3 = {
  wireMagic: 'pb3',
  events: [
    {
      tStartMs: 1000,
      dDurationMs: 2500,
      segs: [
        { utf8: 'hello' },
        { utf8: ' everyone', tOffsetMs: 300 },
        { utf8: ' today', tOffsetMs: 800 },
        { utf8: ' we', tOffsetMs: 1100 },
        { utf8: ' are', tOffsetMs: 1300 },
        { utf8: ' going', tOffsetMs: 1500 },
        { utf8: ' to', tOffsetMs: 1700 },
        { utf8: ' talk', tOffsetMs: 1900 },
        { utf8: ' about', tOffsetMs: 2200 }
      ]
    },
    // 注意：这里下一个 event 在 3500ms 开始，而上一个 event 最后一个词在 1000+2200=3200ms
    // 我们特意制造一个 800ms 的长停顿 (4000ms 开始)
    {
      tStartMs: 4000,
      dDurationMs: 2000,
      segs: [
        { utf8: 'javascript' },
        { utf8: ' browser', tOffsetMs: 350 },
        { utf8: ' extensions', tOffsetMs: 800 }
      ]
    },
    // 制造一个疑问句开头的片段，隔开 600ms
    {
      tStartMs: 6600,
      dDurationMs: 2000,
      segs: [
        { utf8: 'why' },
        { utf8: ' is', tOffsetMs: 250 },
        { utf8: ' this', tOffsetMs: 500 },
        { utf8: ' so', tOffsetMs: 750 },
        { utf8: ' important', tOffsetMs: 1000 }
      ]
    }
  ]
};

console.log('--- 测试 1: 提取词级 Token ---');
const tokens = extractCaptionTokens(mockJson3);
console.log(`成功提取 Token 数量: ${tokens.length}`);
console.assert(tokens.length === 17, `预期 17 个 token，实际: ${tokens.length}`);

console.log('\n--- 测试 2: 智能断句与标点重组 ---');
const sentences = segmentCaptionTokens(tokens, DEFAULT_SETTINGS);

console.log(`生成句子数量: ${sentences.length}`);
sentences.forEach((s) => {
  console.log(`[#${s.id}] [${s.start}ms ~ ${s.end}ms] => "${s.text}"`);
});

// 验证第 1 句末尾补标点且首字母大写
console.assert(sentences.length >= 2, '应该成功分出多句');
console.assert(sentences[0].text.startsWith('Hello'), '第 1 句应该首字母大写');
console.assert(sentences[0].text.endsWith('.'), '第 1 句陈述句应该自动补句号');

// 验证疑问句是否能补问号
const questionSent = sentences.find(s => s.text.toLowerCase().includes('why is this'));
if (questionSent) {
  console.assert(questionSent.text.endsWith('?'), '疑问句应该自动补问号，实际: ' + questionSent.text);
  console.log('✓ 疑问句自动补问号测试通过: ' + questionSent.text);
}

console.log('\n所有单元测试顺利通过！');

import { defineContentScript } from 'wxt/utils/define-content-script';

export default defineContentScript({
  matches: ['*://*.youtube.com/*'],
  world: 'MAIN',
  runAt: 'document_start',
  main() {
    console.log('[YT-Sub-Translator] MAIN world script active.');

    function getPlayer(): any {
      return document.getElementById('movie_player') || document.querySelector('.html5-video-player');
    }

    function getCaptionTracks() {
      const player = getPlayer();
      let tracks = null;

      if (player && typeof player.getCaptionTrackList === 'function') {
        try {
          tracks = player.getCaptionTrackList();
        } catch (e) {}
      }

      if (!tracks || tracks.length === 0) {
        const response = (player && typeof player.getPlayerResponse === 'function')
          ? player.getPlayerResponse()
          : (window as any).ytInitialPlayerResponse;
        tracks = response?.captions?.playerCaptionsTracklistRenderer?.captionTracks || null;
      }

      return tracks;
    }

    function broadcastTracks(reason: string) {
      const tracks = getCaptionTracks();
      const player = getPlayer();
      const videoData = player?.getVideoData?.() || null;

      window.postMessage({
        source: 'YT_SUB_TRANSLATOR_MAIN',
        type: 'CAPTION_TRACKS_FOUND',
        tracks: tracks || [],
        videoData: videoData,
        reason: reason || 'poll'
      }, '*');
    }

    // 监听 Content Script 的指令
    window.addEventListener('message', (event) => {
      if (event.data && event.data.source === 'YT_SUB_TRANSLATOR_CONTENT') {
        if (event.data.action === 'REQUEST_TRACKS') {
          broadcastTracks('request');
        } else if (event.data.action === 'SEEK_TO') {
          const player = getPlayer();
          if (player && typeof player.seekTo === 'function') {
            player.seekTo(event.data.seconds, true);
          }
        }
      }
    });

    // 监听 YouTube SPA 路由与播放器变动事件
    window.addEventListener('yt-navigate-finish', () => {
      setTimeout(() => broadcastTracks('yt-navigate-finish'), 500);
      setTimeout(() => broadcastTracks('yt-navigate-finish-delayed'), 1500);
    });

    // 周期性轮询检测播放器就绪
    let attempts = 0;
    const interval = setInterval(() => {
      attempts++;
      const tracks = getCaptionTracks();
      if (tracks && tracks.length > 0) {
        broadcastTracks('initial_ready');
        clearInterval(interval);
      } else if (attempts > 20) {
        clearInterval(interval);
      }
    }, 800);

    // 页面初次加载广播
    setTimeout(() => broadcastTracks('init'), 300);
  }
});

import type { ExtensionSettings } from '../types';

/**
 * 翻译结果内存缓存 (key: `${targetLang}:${text}`)
 */
const translationCache = new Map<string, string>();

function getCacheKey(targetLang: string, text: string): string {
  return `${targetLang}:${text.trim().toLowerCase()}`;
}

/**
 * 带超时的 fetch 包装
 */
async function fetchWithTimeout(url: string, options: RequestInit = {}, timeoutMs = 6000): Promise<Response> {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);
  try {
    const res = await fetch(url, { ...options, signal: controller.signal });
    clearTimeout(timer);
    return res;
  } catch (err: any) {
    clearTimeout(timer);
    if (err.name === 'AbortError') {
      throw new Error(`请求超时 (${timeoutMs}ms)`);
    }
    throw err;
  }
}

/**
 * 多端点 Google 翻译，支持自动降级
 */
async function translateWithGoogleEndpoints(text: string, targetLang: string): Promise<string> {
  const endpoints = [
    `https://translate.googleapis.com/translate_a/single?client=gtx&sl=auto&tl=${encodeURIComponent(targetLang)}&dt=t&q=${encodeURIComponent(text)}`,
    `https://translate.google.com/translate_a/single?client=gtx&sl=auto&tl=${encodeURIComponent(targetLang)}&dt=t&q=${encodeURIComponent(text)}`
  ];

  let lastError: any = null;
  for (const url of endpoints) {
    try {
      const response = await fetchWithTimeout(url, {}, 5000);
      if (!response.ok) continue;
      const data = await response.json();
      let trans = '';
      if (Array.isArray(data) && Array.isArray(data[0])) {
        for (const seg of data[0]) {
          if (seg && seg[0]) trans += seg[0];
        }
      }
      if (trans.trim()) {
        return trans.trim();
      }
    } catch (err) {
      lastError = err;
    }
  }

  // 备用兜底：MyMemory 免费公开翻译 API (免翻墙备选)
  try {
    const myMemoryUrl = `https://api.mymemory.translated.net/get?q=${encodeURIComponent(text)}&langpair=autodetect|${encodeURIComponent(targetLang)}`;
    const response = await fetchWithTimeout(myMemoryUrl, {}, 5000);
    if (response.ok) {
      const data = await response.json();
      if (data?.responseData?.translatedText) {
        return data.responseData.translatedText;
      }
    }
  } catch (err) {
    // 忽略备用错误
  }

  throw lastError || new Error('所有免费翻译服务均无法访问，可能受当前网络环境限制');
}

/**
 * 批量使用 Google 翻译
 */
async function translateWithGoogle(texts: string[], targetLang: string): Promise<string[]> {
  if (texts.length === 0) return [];

  const results: Array<string | null> = texts.map((t) => translationCache.get(getCacheKey(targetLang, t)) ?? null);
  const uncachedIndices: number[] = [];
  const uncachedTexts: string[] = [];

  for (let i = 0; i < texts.length; i++) {
    if (results[i] === null) {
      uncachedIndices.push(i);
      uncachedTexts.push(texts[i]);
    }
  }

  if (uncachedTexts.length === 0) {
    return results as string[];
  }

  // Google 批量分批（每批 8 句）
  const batchSize = 8;
  for (let i = 0; i < uncachedTexts.length; i += batchSize) {
    const chunkTexts = uncachedTexts.slice(i, i + batchSize);
    const chunkIndices = uncachedIndices.slice(i, i + batchSize);

    const combinedText = chunkTexts.join('\n');
    let batchSuccess = false;

    // 尝试批量请求
    try {
      const transCombined = await translateWithGoogleEndpoints(combinedText, targetLang);
      const lines = transCombined.split('\n').map((l) => l.trim()).filter(Boolean);

      if (lines.length === chunkTexts.length) {
        for (let j = 0; j < chunkTexts.length; j++) {
          const trans = lines[j];
          const gIdx = chunkIndices[j];
          results[gIdx] = trans;
          translationCache.set(getCacheKey(targetLang, chunkTexts[j]), trans);
        }
        batchSuccess = true;
      }
    } catch (e) {
      // 批量失败，降级为单句请求
    }

    // 若批量未能对齐或报错，降级为单句并发请求
    if (!batchSuccess) {
      await Promise.all(
        chunkTexts.map(async (text, subIdx) => {
          const gIdx = chunkIndices[subIdx];
          try {
            const trans = await translateWithGoogleEndpoints(text, targetLang);
            results[gIdx] = trans;
            translationCache.set(getCacheKey(targetLang, text), trans);
          } catch (err: any) {
            console.error('[YT-Sub-Translator] Single translate failed:', err);
            results[gIdx] = `[翻译失败: ${err.message || '网络连接超时'}]`;
          }
        })
      );
    }
  }

  return results.map((r, i) => r ?? texts[i]);
}

/**
 * OpenAI / DeepSeek 等兼容接口批量翻译
 */
async function translateWithOpenAICompatible(
  texts: string[],
  targetLang: string,
  settings: ExtensionSettings
): Promise<string[]> {
  const { apiKey, apiBaseUrl, service, modelName } = settings;
  if (!apiKey) {
    throw new Error('未配置 API Key，请在插件设置中填入');
  }

  let baseUrl = apiBaseUrl?.trim();
  if (!baseUrl) {
    if (service === 'deepseek') {
      baseUrl = 'https://api.deepseek.com/v1';
    } else {
      baseUrl = 'https://api.openai.com/v1';
    }
  }
  baseUrl = baseUrl.replace(/\/+$/, '');
  const endpoint = `${baseUrl}/chat/completions`;
  const model = modelName?.trim() || (service === 'deepseek' ? 'deepseek-chat' : 'gpt-4o-mini');

  const payloadItems = texts.map((text, id) => ({ id, text }));

  const systemPrompt = `你是一位精通视频双语字幕翻译的资深专家。
任务：将用户提供的多句视频字幕原文翻译为目标语言：${targetLang}。
要求：
1. 语言地道自然，符合影视口语化表达习惯，简练通顺。
2. 保持上下文连贯，准确处理前后句的代词指代。
3. 必须严格输出 JSON 数组格式，不要包含任何 markdown 解释或代码块标记，结构如下：
[{"id": 0, "translation": "..."}, {"id": 1, "translation": "..."}]`;

  const response = await fetchWithTimeout(
    endpoint,
    {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        Authorization: `Bearer ${apiKey}`
      },
      body: JSON.stringify({
        model,
        messages: [
          { role: 'system', content: systemPrompt },
          { role: 'user', content: JSON.stringify(payloadItems) }
        ],
        temperature: 0.3
      })
    },
    15000
  );

  if (!response.ok) {
    const errText = await response.text();
    throw new Error(`AI 接口请求失败 (${response.status}): ${errText}`);
  }

  const data = await response.json();
  const rawContent = data.choices?.[0]?.message?.content || '';
  const cleaned = rawContent.replace(/```(?:json)?/gi, '').replace(/```/g, '').trim();
  const parsed = JSON.parse(cleaned) as Array<{ id: number; translation: string }>;

  const transMap = new Map<number, string>();
  for (const item of parsed) {
    transMap.set(item.id, item.translation);
  }

  return texts.map((t, idx) => {
    const res = transMap.get(idx) || t;
    translationCache.set(getCacheKey(targetLang, t), res);
    return res;
  });
}

/**
 * Gemini API 翻译
 */
async function translateWithGemini(
  texts: string[],
  targetLang: string,
  settings: ExtensionSettings
): Promise<string[]> {
  const { apiKey, modelName } = settings;
  if (!apiKey) {
    throw new Error('未配置 Gemini API Key，请在插件设置中填入');
  }

  const model = modelName?.trim() || 'gemini-1.5-flash';
  const endpoint = `https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent?key=${apiKey}`;

  const payloadItems = texts.map((text, id) => ({ id, text }));
  const prompt = `你是一位专业视频字幕翻译家。请将以下按顺序给出的英文视频断句翻译成目标语言：${targetLang}。
保持口语自然、用词地道。
请直接返回 JSON 格式，不要使用任何多余文字或 markdown：
[{"id": 0, "translation": "..."}, ...]

待翻译内容：
${JSON.stringify(payloadItems)}`;

  const response = await fetchWithTimeout(
    endpoint,
    {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        contents: [{ parts: [{ text: prompt }] }],
        generationConfig: {
          responseMimeType: 'application/json'
        }
      })
    },
    15000
  );

  if (!response.ok) {
    const errText = await response.text();
    throw new Error(`Gemini API 错误 (${response.status}): ${errText}`);
  }

  const data = await response.json();
  const rawText = data.candidates?.[0]?.content?.parts?.[0]?.text || '';
  const parsed = JSON.parse(rawText) as Array<{ id: number; translation: string }>;

  const transMap = new Map<number, string>();
  for (const item of parsed) {
    transMap.set(item.id, item.translation);
  }

  return texts.map((t, idx) => {
    const res = transMap.get(idx) || t;
    translationCache.set(getCacheKey(targetLang, t), res);
    return res;
  });
}

/**
 * 统一分发翻译入口
 */
export async function translateSentenceBatch(
  texts: string[],
  targetLang: string,
  settings: ExtensionSettings
): Promise<string[]> {
  if (texts.length === 0) return [];

  const service = settings.service || 'google';

  try {
    switch (service) {
      case 'deepseek':
      case 'openai':
        return await translateWithOpenAICompatible(texts, targetLang, settings);
      case 'gemini':
        return await translateWithGemini(texts, targetLang, settings);
      case 'google':
      default:
        return await translateWithGoogle(texts, targetLang);
    }
  } catch (error: any) {
    console.warn(`[YT-Sub-Translator] ${service} 翻译发生错误:`, error);
    if (service !== 'google') {
      // 若大模型配置错误或欠费，尝试降级回免费 Google 翻译
      try {
        return await translateWithGoogle(texts, targetLang);
      } catch {
        // 若全部失败，返回带错误原因的译文，让用户能直观看到原因
        return texts.map((t) => `[翻译异常: ${error.message || '网络连接失败'}]`);
      }
    }
    return texts.map((t) => `[翻译失败: ${error.message || '网络无法直连翻译接口'}]`);
  }
}

import { defineConfig } from 'wxt';

export default defineConfig({
