/**
 * 在 YouTube 播放器控制栏右侧注入类似沉浸式翻译的快捷图标
 */
function injectControlBarButton(player: HTMLElement) {
  const rightControls = player.querySelector('.ytp-right-controls');
  if (!rightControls) return;

  if (controlBarButton && controlBarButton.parentElement === rightControls) {
    updateControlBarButtonState();
    return;
  }

  const existing = rightControls.querySelector('.ytp-sub-translator-btn');
  if (existing) existing.remove();

  controlBarButton = document.createElement('button');
  controlBarButton.className = 'ytp-button ytp-sub-translator-btn';
  controlBarButton.setAttribute('aria-label', '智能字幕断句与翻译设置');
  controlBarButton.setAttribute('title', '智能字幕断句与翻译 (点击快速设置)');
  controlBarButton.style.cssText = `
    display: inline-flex;
    align-items: center;
    justify-content: center;
    vertical-align: top;
    width: 38px;
    height: 100%;
    cursor: pointer;
    background: transparent;
    border: none;
    outline: none;
    padding: 0;
    margin: 0 4px;
    position: relative;
  `;

  controlBarButton.innerHTML = getControlBarButtonInnerHtml(settings?.enabled ?? true);

  controlBarButton.addEventListener('click', (e) => {
    e.stopPropagation();
    e.preventDefault();
    if (overlay) {
      overlay.toggleQuickPanel();
    }
  });

  // 优先插入到自动播放开关或字幕按钮前
  const refChild =
    rightControls.querySelector('.ytp-autonav-toggle-button') ||
    rightControls.querySelector('.ytp-subtitles-button') ||
    rightControls.firstChild;
  if (refChild) {
    rightControls.insertBefore(controlBarButton, refChild);
  } else {
    rightControls.appendChild(controlBarButton);
  }
}

