async function check() {
  const videoId = 'XHI2asm60G4';
  try {
    const res = await fetch('https://www.youtube.com/watch?v=' + videoId, {
      headers: {
        'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36',
        'Accept-Language': 'ja,en;q=0.9'
      }
    });
    const html = await res.text();
    console.log('HTML length:', html.length);
    console.log('Includes captionTracks:', html.includes('captionTracks'));

    const m = html.match(/"captionTracks":\s*(\[.+?\])/);
    if (m) {
      console.log('captionTracks found:', m[1].slice(0, 500));
    } else {
      console.log('No captionTracks in HTML');
      const playerRespMatch = html.match(/ytInitialPlayerResponse\s*=\s*(\{.+?\});/s);
      if (playerRespMatch) {
        console.log('ytInitialPlayerResponse exists!');
        try {
          const pr = JSON.parse(playerRespMatch[1]);
          console.log('Captions field in pr:', pr.captions);
        } catch (e) {
          console.log('Failed parse pr:', e.message);
        }
      } else {
        console.log('No ytInitialPlayerResponse found in HTML');
      }
    }
  } catch (e) {
    console.error('Error:', e);
  }
}

check();

async function testCaptionFetch() {
  const videoId = 'XHI2asm60G4';
  const res = await fetch('https://www.youtube.com/watch?v=' + videoId, {
    headers: {
      'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64)',
      'Accept-Language': 'ja,en;q=0.9'
    }
  });
  const html = await res.text();
  const m = html.match(/"captionTracks":\s*(\[.+?\])/);
  if (!m) {
    console.log('No captionTracks match');
    return;
  }
  const tracks = JSON.parse(m[1]);
  console.log('Tracks count:', tracks.length);
  const jaTrack = tracks[0];
  console.log('Track:', jaTrack.name, jaTrack.languageCode, jaTrack.kind);

  const json3Url = jaTrack.baseUrl + '&fmt=json3';
  console.log('Fetching json3:', json3Url);

  const captionRes = await fetch(json3Url);
  console.log('Caption HTTP status:', captionRes.status);
  const captionData = await captionRes.json();
  console.log('Total events in captionData:', captionData.events?.length);

  // 找 3736s (3736000ms) 附近的 events
  const targetMs = 3736000;
  const nearby = (captionData.events || []).filter(e => Math.abs(e.tStartMs - targetMs) < 60000);
  console.log('Nearby events count around 3736s:', nearby.length);
  if (nearby.length > 0) {
    console.log('Sample nearby event:', JSON.stringify(nearby.slice(0, 5), null, 2));
  } else {
    // 打印最后几个 event 看视频总时长字幕到哪里
    const lastEvents = (captionData.events || []).slice(-5);
    console.log('Last events:', JSON.stringify(lastEvents, null, 2));
  }
}

