import puppeteer from 'puppeteer-core';
import path from 'path';

async function run() {
  const extensionPath = path.resolve('.output/chrome-mv3');
  const edgePath = 'C:\\Program Files (x86)\\Microsoft\\Edge\\Application\\msedge.exe';
  const targetUrl = 'https://www.youtube.com/watch?v=XHI2asm60G4&t=3736s';

  console.log('Launching Edge with extension:', extensionPath);

  const browser = await puppeteer.launch({
    executablePath: edgePath,
    headless: false, // 打开可见窗口以便观察实际页面
    defaultViewport: null,
    args: [
      `--disable-extensions-except=${extensionPath}`,
      `--load-extension=${extensionPath}`,
      '--no-sandbox',
      '--disable-setuid-sandbox',
      '--autoplay-policy=no-user-gesture-required',
      '--window-size=1280,800'
    ]
  });

  const pages = await browser.pages();
  const page = pages[0] || await browser.newPage();

  // 监听浏览器 Console
  page.on('console', (msg) => {
    const text = msg.text();
    if (text.includes('YT-Sub') || text.includes('caption') || text.includes('error') || text.includes('Error')) {
      console.log(`[Browser Console] ${msg.type().toUpperCase()}: ${text}`);
    }
  });

  page.on('pageerror', (err) => {
    console.log(`[Browser PageError]:`, err.message);
  });

  // 监听 timedtext 网络请求
  page.on('response', async (res) => {
    const url = res.url();
    if (url.includes('timedtext')) {
      console.log(`[Network Response] timedtext: status=${res.status()}`);
      try {
        const body = await res.text();
        console.log(`[Network Response] timedtext body length: ${body.length}, preview: ${body.slice(0, 150)}`);
      } catch (e) {
        console.log(`[Network Response] timedtext read error:`, e.message);
      }
    }
  });

  console.log('Navigating to:', targetUrl);
  try {
    await page.goto(targetUrl, { waitUntil: 'domcontentloaded', timeout: 30000 });
  } catch (e) {
    console.log('Navigation warning:', e.message);
  }

  console.log('Waiting for player to initialize...');
  await page.waitForTimeout ? page.waitForTimeout(6000) : new Promise(r => setTimeout(r, 6000));

  // 检查播放器 DOM 和字幕音轨
  const diagnostic = await page.evaluate(() => {
    const player = document.getElementById('movie_player') as any;
    const rightControls = document.querySelector('.ytp-right-controls');
    const customBtn = document.querySelector('.yt-sub-translator-cbar-btn');
    const host = document.getElementById('yt-sub-translator-host');
    const ccBtn = document.querySelector('.ytp-subtitles-button') as HTMLElement;
    const video = document.querySelector('video') as HTMLVideoElement;

    let tracks = null;
    let trackList = null;
    if (player) {
      if (typeof player.getCaptionTrackList === 'function') {
        try { trackList = player.getCaptionTrackList(); } catch (e) {}
      }
      if (typeof player.getPlayerResponse === 'function') {
        try {
          const resp = player.getPlayerResponse();
          tracks = resp?.captions?.playerCaptionsTracklistRenderer?.captionTracks;
        } catch (e) {}
      }
    }

    // 检查 CC 按钮状态
    const isCcPressed = ccBtn ? ccBtn.getAttribute('aria-pressed') : 'no_btn';

    return {
      hasPlayer: !!player,
      hasRightControls: !!rightControls,
      hasCustomButton: !!customBtn,
      hasHost: !!host,
      isCcPressed,
      trackListCount: trackList ? trackList.length : 0,
      tracksCount: tracks ? tracks.length : 0,
      tracks: tracks || trackList,
      currentTime: video ? video.currentTime : 0,
      paused: video ? video.paused : true
    };
  });

  console.log('--- Diagnostic Results ---');
  console.log(JSON.stringify(diagnostic, null, 2));

  // 截图验证当前播放器状态
  await page.screenshot({ path: 'browser-verification.png' });
  console.log('Saved screenshot to browser-verification.png');

  // 再等待 5 秒观察时间更新
  await new Promise(r => setTimeout(r, 5000));

  await browser.close();
  console.log('Browser test finished.');
}

run().catch(console.error);

