import puppeteer from 'puppeteer-core';
import path from 'path';

async function testNativeCC() {
  const extensionPath = path.resolve('.output/chrome-mv3');
  const edgePath = 'C:\\Program Files (x86)\\Microsoft\\Edge\\Application\\msedge.exe';
  const targetUrl = 'https://www.youtube.com/watch?v=XHI2asm60G4&t=3736s';

  console.log('Testing Native CC Request in Edge...');
  const browser = await puppeteer.launch({
    executablePath: edgePath,
    headless: false,
    args: [
      `--disable-extensions-except=${extensionPath}`,
      `--load-extension=${extensionPath}`,
      '--no-sandbox',
      '--autoplay-policy=no-user-gesture-required',
      '--window-size=1280,800'
    ]
  });

  const page = (await browser.pages())[0] || await browser.newPage();

  page.on('request', (req) => {
    const url = req.url();
    if (url.includes('timedtext')) {
      console.log('>>> [Intercepted Request URL]:', url);
      console.log('>>> [Headers]:', req.headers());
    }
  });

  page.on('response', async (res) => {
    const url = res.url();
    if (url.includes('timedtext')) {
      console.log('<<< [Intercepted Response Status]:', res.status());
      try {
        const text = await res.text();
        console.log('<<< [Response Body Length]:', text.length);
        if (text.length > 0) {
          console.log('<<< [Response Content Preview]:', text.slice(0, 300));
        }
      } catch (e) {
        console.log('<<< [Response Error]:', e.message);
      }
    }
  });

  await page.goto(targetUrl, { waitUntil: 'domcontentloaded', timeout: 30000 });
  await new Promise(r => setTimeout(r, 4000));

  // 点击播放视频与点击 CC 按钮
  await page.evaluate(() => {
    const video = document.querySelector('video');
    if (video) video.play();

    const ccBtn = document.querySelector('.ytp-subtitles-button') as HTMLElement;
    if (ccBtn && ccBtn.getAttribute('aria-pressed') !== 'true') {
      console.log('Clicking CC button to enable subtitles...');
      ccBtn.click();
    }
  });

  await new Promise(r => setTimeout(r, 6000));

  // 检查此时 DOM 中是否有字幕文本
  const captionText = await page.evaluate(() => {
    const segs = document.querySelectorAll('.ytp-caption-segment');
    return Array.from(segs).map(s => s.textContent).join(' ');
  });

  console.log('Current DOM Subtitle Text:', captionText || '(EMPTY IN DOM)');

  await browser.close();
}

testNativeCC().catch(console.error);

/**
 * YouTube 播放器控制栏快捷按钮注入器
 * 确保在各种模式（常规、剧场、全屏、SPA路由切换）下 100% 稳定存在
 */

export interface ControlButtonCallbacks {
  onClick: () => void;
}

export class ControlBarButtonManager {
  private buttonEl: HTMLElement | null = null;
  private isEnabled: boolean = true;
  private callbacks: ControlButtonCallbacks;
  private checkTimer: any = null;

  constructor(callbacks: ControlButtonCallbacks, initialEnabled = true) {
    this.callbacks = callbacks;
    this.isEnabled = initialEnabled;
  }

  public init() {
    this.startWatchdog();
  }

  public setEnabled(enabled: boolean) {
    this.isEnabled = enabled;
    this.updateStyle();
  }

  public updateStyle() {
    if (!this.buttonEl) return;
    const inner = this.buttonEl.querySelector('.yt-sub-btn-inner') as HTMLElement;
    if (inner) {
      if (this.isEnabled) {
        inner.style.background = 'linear-gradient(135deg, #f43f5e, #fb7185)';
        inner.style.boxShadow = '0 2px 10px rgba(244, 63, 94, 0.55)';
        inner.style.opacity = '1';
      } else {
        inner.style.background = 'rgba(255, 255, 255, 0.2)';
        inner.style.boxShadow = 'none';
        inner.style.opacity = '0.65';
      }
    }
  }

  public checkAndMount() {
    const player = document.getElementById('movie_player') || document.querySelector('.html5-video-player');
    if (!player) return;

    const rightControls = player.querySelector('.ytp-right-controls');
    if (!rightControls) return;

    // 检查按钮是否已经在 DOM 树中并且处于可见状态
    if (this.buttonEl && document.body.contains(this.buttonEl)) {
      return;
    }

    this.createButton();

    if (this.buttonEl) {
      // 优先找到自动播放按钮或字幕按钮，用 insertAdjacentElement 安全插入
      const refEl =
        rightControls.querySelector('.ytp-autonav-toggle-button') ||
        rightControls.querySelector('.ytp-subtitles-button') ||
        rightControls.querySelector('.ytp-settings-button');

      if (refEl) {
        // 使用 insertAdjacentElement 彻底避免 insertBefore 的父节点不匹配异常
        refEl.insertAdjacentElement('beforebegin', this.buttonEl);
      } else if (rightControls.firstChild) {
        (rightControls.firstChild as HTMLElement).insertAdjacentElement('beforebegin', this.buttonEl);
      } else {
        rightControls.appendChild(this.buttonEl);
      }
    }
  }

  private createButton() {
    if (this.buttonEl) {
      this.buttonEl.remove();
    }

    const btn = document.createElement('button');
    btn.className = 'ytp-button yt-sub-translator-cbar-btn';
    btn.setAttribute('aria-label', '智能字幕断句与翻译设置');
    btn.setAttribute('title', '智能字幕断句与翻译 (点击打开设置与调色面板)');
    btn.style.cssText = `
      display: inline-flex !important;
      align-items: center !important;
      justify-content: center !important;
      vertical-align: top !important;
      width: 40px !important;
      height: 100% !important;
      cursor: pointer !important;
      background: transparent !important;
      border: none !important;
      outline: none !important;
      padding: 0 !important;
      margin: 0 4px !important;
      position: relative !important;
      visibility: visible !important;
      opacity: 1 !important;
      z-index: 60 !important;
    `;

    const bg = this.isEnabled
      ? 'background: linear-gradient(135deg, #f43f5e, #fb7185); box-shadow: 0 2px 10px rgba(244, 63, 94, 0.55); opacity: 1;'
      : 'background: rgba(255, 255, 255, 0.2); box-shadow: none; opacity: 0.65;';

    btn.innerHTML = `
      <div class="yt-sub-btn-inner" style="
        width: 30px;
        height: 28px;
        border-radius: 8px;
        display: flex;
        align-items: center;
        justify-content: center;
        ${bg}
        transition: transform 0.15s ease, box-shadow 0.15s ease, opacity 0.15s ease;
      ">
        <svg viewBox="0 0 28 28" width="20" height="20" fill="none" xmlns="http://www.w3.org/2000/svg">
          <path d="M7 3.5L7.9 6.1L10.5 7L7.9 7.9L7 10.5L6.1 7.9L3.5 7L6.1 6.1L7 3.5Z" fill="#ffffff"/>
          <path d="M16 8L11.5 20H13.8L14.7 17.5H19.3L20.2 20H22.5L18 8H16ZM15.4 15.6L17 11L18.6 15.6H15.4Z" fill="#ffffff"/>
          <path d="M6.5 16C6.5 18.5 8.5 20 11 20" stroke="#ffffff" stroke-width="1.8" stroke-linecap="round"/>
        </svg>
      </div>
    `;

    btn.addEventListener('mouseenter', () => {
      const inner = btn.querySelector('.yt-sub-btn-inner') as HTMLElement;
      if (inner) inner.style.transform = 'scale(1.08)';
    });
    btn.addEventListener('mouseleave', () => {
      const inner = btn.querySelector('.yt-sub-btn-inner') as HTMLElement;
      if (inner) inner.style.transform = 'scale(1)';
    });

    btn.addEventListener('click', (e) => {
      e.stopPropagation();
      e.preventDefault();
      this.callbacks.onClick();
    });

    this.buttonEl = btn;
  }

  private startWatchdog() {
    this.checkAndMount();

    // 守护定时器：确保在全屏切换、广告结束、单页跳转后按钮稳定可见
    this.checkTimer = setInterval(() => {
      this.checkAndMount();
    }, 800);

    window.addEventListener('yt-navigate-finish', () => {
      setTimeout(() => this.checkAndMount(), 300);
      setTimeout(() => this.checkAndMount(), 1000);
    });
    document.addEventListener('fullscreenchange', () => {
      setTimeout(() => this.checkAndMount(), 200);
    });
  }

  public destroy() {
    if (this.checkTimer) clearInterval(this.checkTimer);
    if (this.buttonEl) {
      this.buttonEl.remove();
      this.buttonEl = null;
    }
  }
}

