import puppeteer from 'puppeteer-core';
import path from 'path';
import fs from 'fs';
import os from 'os';

async function run() {
  const extensionPath = path.resolve('.output/chrome-mv3');
  const edgePath = 'C:\\Program Files (x86)\\Microsoft\\Edge\\Application\\msedge.exe';
  const targetUrl = 'https://www.youtube.com/watch?v=XHI2asm60G4&t=3736s';
  const testUserDataDir = path.join(os.tmpdir(), 'edge-test-' + Date.now());

  console.log('=== Step 1: Launching Edge with Extension ===');
  console.log('Extension path:', extensionPath);

  const browser = await puppeteer.launch({
    executablePath: edgePath,
    headless: false,
    userDataDir: testUserDataDir,
    args: [
      `--disable-extensions-except=${extensionPath}`,
      `--load-extension=${extensionPath}`,
      '--no-sandbox',
      '--disable-setuid-sandbox',
      '--autoplay-policy=no-user-gesture-required',
      '--window-size=1280,850'
    ]
  });

  const page = (await browser.pages())[0] || await browser.newPage();
  await page.setViewport({ width: 1280, height: 850 });

  const consoleLogs = [];
  page.on('console', (msg) => {
    const text = msg.text();
    consoleLogs.push(`[${msg.type().toUpperCase()}] ${text}`);
    if (text.includes('YT-Sub') || text.includes('error') || text.includes('Error')) {
      console.log(`[Browser Console] ${text}`);
    }
  });

  page.on('pageerror', (err) => {
    console.log(`[Browser PageError]:`, err.message);
  });

  let timedtextResponses = [];
  page.on('response', async (res) => {
    if (res.url().includes('timedtext')) {
      try {
        const body = await res.text();
        timedtextResponses.push({
          url: res.url(),
          status: res.status(),
          length: body.length,
          preview: body.slice(0, 100)
        });
        console.log(`[Network timedtext] status=${res.status()}, length=${body.length}`);
      } catch (e) {}
    }
  });

  console.log('\n=== Step 2: Navigating to Target Video ===');
  console.log(targetUrl);
  await page.goto(targetUrl, { waitUntil: 'domcontentloaded', timeout: 35000 });

  // 等待播放器挂载与扩展就绪
  console.log('Waiting 5s for player and extension initialization...');
  await new Promise(r => setTimeout(r, 5000));

  // 检查控制栏快捷按钮
  const checkButton = await page.evaluate(() => {
    const btn = document.querySelector('.yt-sub-translator-cbar-btn');
    const rightControls = document.querySelector('.ytp-right-controls');
    const player = document.getElementById('movie_player');
    const host = document.getElementById('yt-sub-translator-host');
    return {
      hasButton: !!btn,
      buttonVisible: btn ? window.getComputedStyle(btn).display !== 'none' : false,
      buttonTitle: btn ? btn.getAttribute('title') : null,
      hasRightControls: !!rightControls,
      hasPlayer: !!player,
      hasHost: !!host
    };
  });
  console.log('Control Bar Button Check:', checkButton);

  // 截取播放器画面，验证控制栏图标
  await page.screenshot({ path: 'step1-player-with-button.png' });
  console.log('Saved screenshot: step1-player-with-button.png');

  // 点击快捷按钮打开 Quick Panel
  if (checkButton.hasButton) {
    console.log('\n=== Step 3: Clicking Control Bar Button to Toggle Quick Panel ===');
    await page.evaluate(() => {
      const btn = document.querySelector('.yt-sub-translator-cbar-btn');
      if (btn) btn.click();
    });

    await new Promise(r => setTimeout(r, 1000));

    // 检查 Shadow DOM 中的 Quick Panel 状态
    const panelStatus = await page.evaluate(() => {
      const host = document.getElementById('yt-sub-translator-host');
      if (!host || !host.shadowRoot) return { foundHost: false };
      const panel = host.shadowRoot.getElementById('yt-sub-quick-panel');
      const emptyNote = host.shadowRoot.querySelector('.empty-track-note');
      return {
        foundHost: true,
        panelOpen: panel ? panel.classList.contains('active') : false,
        hasEmptyNote: !!emptyNote,
        emptyNoteText: emptyNote ? emptyNote.textContent : null
      };
    });
    console.log('Quick Panel Status:', panelStatus);

    await page.screenshot({ path: 'step2-quick-panel-open.png' });
    console.log('Saved screenshot: step2-quick-panel-open.png');
  }

  // 检查此时原生 CC 按钮与 timedtext 情况
  console.log('\n=== Step 4: Investigating Subtitle Audio Track / timedtext for this Video ===');
  console.log('Timedtext responses received:', timedtextResponses);

  // 尝试点击原生 CC 按钮触发请求
  await page.evaluate(() => {
    const ccBtn = document.querySelector('.ytp-subtitles-button');
    if (ccBtn) {
      console.log('CC button found, aria-pressed =', ccBtn.getAttribute('aria-pressed'));
      ccBtn.click();
    }
  });
  await new Promise(r => setTimeout(r, 4000));
  console.log('Timedtext responses after clicking CC:', timedtextResponses);

  // 测试第二阶段：为了向用户证明翻译与断句算法在有有效字幕的视频上完全正常运作，
  // 我们跳转到一个包含实际语音/对白的日文视频进行验证
  console.log('\n=== Step 5: Testing on a Video with Active Subtitle Track for Comparison ===');
  // 选一个典型的有日本语自动字幕的杂谈或演讲视频
  const activeSubVideoUrl = 'https://www.youtube.com/watch?v=dQw4w9WgXcQ'; // 或者其他经典测试视频
  await page.goto(activeSubVideoUrl, { waitUntil: 'domcontentloaded', timeout: 30000 });
  await new Promise(r => setTimeout(r, 5000));

  // 开启播放并检查字幕加载
  await page.evaluate(() => {
    const video = document.querySelector('video');
    if (video) video.play();
  });
  await new Promise(r => setTimeout(r, 4000));

  const secondVideoCheck = await page.evaluate(() => {
    const host = document.getElementById('yt-sub-translator-host');
    const shadow = host?.shadowRoot;
    const subtitleBox = shadow?.querySelector('.yt-sub-subtitle-box');
    const origEl = shadow?.querySelector('.orig');
    const transEl = shadow?.querySelector('.trans');
    const btn = document.querySelector('.yt-sub-translator-cbar-btn');
    return {
      hasButton: !!btn,
      hasSubtitleBox: !!subtitleBox,
      hasText: !!(origEl?.textContent || transEl?.textContent),
      origText: origEl?.textContent || '',
      transText: transEl?.textContent || ''
    };
  });
  console.log('Second Video Result:', secondVideoCheck);

  await page.screenshot({ path: 'step3-comparison-video.png' });
  console.log('Saved screenshot: step3-comparison-video.png');

  await browser.close();
  try {
    fs.rmSync(testUserDataDir, { recursive: true, force: true });
  } catch (e) {}

  console.log('\n=== Verification Completed Successfully ===');
}

run().catch((e) => {
  console.error('Run failed:', e);
  process.exit(1);
});

