import puppeteer from 'puppeteer-core';
import path from 'path';
import fs from 'fs';
import os from 'os';

async function run() {
  const extensionPath = path.resolve('.output/chrome-mv3');
  const edgePath = 'C:\\Program Files (x86)\\Microsoft\\Edge\\Application\\msedge.exe';
  const targetUrl = 'https://www.youtube.com/watch?v=XHI2asm60G4&t=3736s';
  const testUserDataDir = path.join(os.tmpdir(), 'edge-verify-' + Date.now());

  console.log('=== Step 1: Launching Edge with Extension ===');
  console.log('Extension path:', extensionPath);

  const browser = await puppeteer.launch({
    executablePath: edgePath,
    headless: false,
    userDataDir: testUserDataDir,
    args: [
      `--disable-extensions-except=${extensionPath}`,
      `--load-extension=${extensionPath}`,
      '--no-sandbox',
      '--disable-setuid-sandbox',
      '--autoplay-policy=no-user-gesture-required',
      '--window-size=1280,850'
    ]
  });

  const page = (await browser.pages())[0] || await browser.newPage();
  await page.setViewport({ width: 1280, height: 850 });

  page.on('console', (msg) => {
    const text = msg.text();
    if (text.includes('YT-Sub') || text.includes('Error') || text.includes('error')) {
      console.log(`[Browser Console] ${text}`);
    }
  });

  let timedtextReceived = [];
  page.on('response', async (res) => {
    if (res.url().includes('timedtext')) {
      try {
        const body = await res.text();
        timedtextReceived.push({
          url: res.url().slice(0, 100),
          status: res.status(),
          length: body.length
        });
        console.log(`[Network Response] timedtext status=${res.status()}, length=${body.length}`);
      } catch (e) {}
    }
  });

  console.log('\n=== Step 2: Navigating to Target User Video ===');
  console.log(targetUrl);
  await page.goto(targetUrl, { waitUntil: 'domcontentloaded', timeout: 35000 });

  console.log('Waiting 6s for YouTube and extension initialization...');
  await new Promise(r => setTimeout(r, 6000));

  // 检查控制栏上的快捷按钮
  const btnDiagnostic = await page.evaluate(() => {
    const btn = document.querySelector('.yt-sub-translator-cbar-btn');
    const rightControls = document.querySelector('.ytp-right-controls');
    return {
      hasBtn: !!btn,
      btnVisible: btn ? window.getComputedStyle(btn).display !== 'none' : false,
      rightControlsChildrenCount: rightControls ? rightControls.children.length : 0
    };
  });
  console.log('Control Bar Button Diagnostic:', btnDiagnostic);

  // 截图验证按钮已成功注入控制栏
  await page.screenshot({ path: 'verification-step1-player.png' });
  console.log('Saved: verification-step1-player.png');

  // 点击快捷按钮，弹出 Quick Panel
  if (btnDiagnostic.hasBtn) {
    console.log('\n=== Step 3: Clicking Control Bar Button to Toggle Quick Panel ===');
    await page.evaluate(() => {
      const btn = document.querySelector('.yt-sub-translator-cbar-btn');
      if (btn) btn.click();
    });

    await new Promise(r => setTimeout(r, 1200));

    const panelCheck = await page.evaluate(() => {
      const host = document.getElementById('yt-sub-translator-host');
      const panel = host?.shadowRoot?.querySelector('.quick-panel');
      const statusText = host?.shadowRoot?.getElementById('qp-track-status')?.textContent;
      return {
        hasHost: !!host,
        panelOpen: panel ? panel.classList.contains('open') : false,
        statusText: statusText || ''
      };
    });
    console.log('Quick Panel Check:', panelCheck);

    // 截图验证 Quick Panel（调色板、字号、场景切换等）正常展示
    await page.screenshot({ path: 'verification-step2-quick-panel.png' });
    console.log('Saved: verification-step2-quick-panel.png');
  }

  // 点击原生 CC 按钮触发 YouTube 网络请求
  console.log('\n=== Step 4: Clicking Native CC to test timedtext from YouTube ===');
  await page.evaluate(() => {
    const ccBtn = document.querySelector('.ytp-subtitles-button');
    if (ccBtn) ccBtn.click();
  });
  await new Promise(r => setTimeout(r, 4000));

  const ccStatus = await page.evaluate(() => {
    const ccBtn = document.querySelector('.ytp-subtitles-button');
    const segs = document.querySelectorAll('.ytp-caption-segment');
    return {
      ariaPressed: ccBtn ? ccBtn.getAttribute('aria-pressed') : 'null',
      segsCount: segs.length,
      segsText: Array.from(segs).map(s => s.textContent).join(' ')
    };
  });
  console.log('CC Status & DOM captions:', ccStatus);
  console.log('Timedtext responses:', timedtextReceived);

  // 接下来测试一个有确凿 ASR 语音字幕的对比视频（Steve Jobs 经典 Stanford 演讲）
  console.log('\n=== Step 5: Testing on an Active ASR Subtitled Video (Comparison Verification) ===');
  const compUrl = 'https://www.youtube.com/watch?v=UF8uR6Z6KLc';
  await page.goto(compUrl, { waitUntil: 'domcontentloaded', timeout: 35000 });
  await new Promise(r => setTimeout(r, 6000));

  // 播放视频
  await page.evaluate(() => {
    const video = document.querySelector('video');
    if (video) video.play();
  });

  console.log('Waiting 6s for captions fetch, segmentation, and translation pipeline...');
  await new Promise(r => setTimeout(r, 6000));

  const compResult = await page.evaluate(() => {
    const host = document.getElementById('yt-sub-translator-host');
    const shadow = host?.shadowRoot;
    const box = shadow?.querySelector('.subtitle-box');
    const orig = shadow?.querySelector('.original-text')?.textContent;
    const trans = shadow?.querySelector('.translated-text')?.textContent;
    const status = shadow?.querySelector('.status-indicator')?.textContent;
    return {
      hasHost: !!host,
      boxActive: box ? box.classList.contains('active') : false,
      origText: orig || '',
      transText: trans || '',
      statusText: status || ''
    };
  });
  console.log('Comparison Video Result:', compResult);

  await page.screenshot({ path: 'verification-step3-active-subtitles.png' });
  console.log('Saved: verification-step3-active-subtitles.png');

  await browser.close();
  try {
    fs.rmSync(testUserDataDir, { recursive: true, force: true });
  } catch (e) {}

  console.log('\n=== Verification Process Complete ===');
}

run().catch((e) => {
  console.error('Test execution failed:', e);
  process.exit(1);
});

