import puppeteer from 'puppeteer-core';

async function testMainWorld() {
  const edgePath = 'C:\\Program Files (x86)\\Microsoft\\Edge\\Application\\msedge.exe';
  const targetUrl = 'https://www.youtube.com/watch?v=UF8uR6Z6KLc'; // 经典视频

  const browser = await puppeteer.launch({
    executablePath: edgePath,
    headless: false,
    args: ['--no-sandbox', '--window-size=1280,800']
  });

  const page = (await browser.pages())[0] || await browser.newPage();

  // 在页面加载之前注入 hook 监听 fetch 和 XHR
  await page.evaluateOnNewDocument(() => {
    window.__capturedTimedtext = [];

    // Hook fetch
    const origFetch = window.fetch;
    window.fetch = async function(...args) {
      const url = typeof args[0] === 'string' ? args[0] : (args[0] && args[0].url ? args[0].url : '');
      const response = await origFetch.apply(this, args);
      if (url.includes('timedtext')) {
        try {
          const clone = response.clone();
          const text = await clone.text();
          window.__capturedTimedtext.push({
            type: 'fetch',
            url,
            status: response.status,
            length: text.length,
            preview: text.slice(0, 200)
          });
        } catch (e) {}
      }
      return response;
    };

    // Hook XMLHttpRequest
    const origOpen = XMLHttpRequest.prototype.open;
    const origSend = XMLHttpRequest.prototype.send;
    XMLHttpRequest.prototype.open = function(method, url, ...rest) {
      this.__url = url;
      return origOpen.call(this, method, url, ...rest);
    };
    XMLHttpRequest.prototype.send = function(...args) {
      if (this.__url && String(this.__url).includes('timedtext')) {
        this.addEventListener('load', () => {
          try {
            window.__capturedTimedtext.push({
              type: 'xhr',
              url: this.__url,
              status: this.status,
              length: (this.responseText || '').length,
              preview: (this.responseText || '').slice(0, 200)
            });
          } catch (e) {}
        });
      }
      return origSend.apply(this, args);
    };
  });

  await page.goto(targetUrl, { waitUntil: 'domcontentloaded' });
  await new Promise(r => setTimeout(r, 4000));

  // 在播放器中切换字幕语言并开启字幕
  const playerResult = await page.evaluate(async () => {
    const player = document.getElementById('movie_player');
    const logs = [];

    if (player) {
      // 查看 player 上所有与 caption 相关的方法
      const props = [];
      for (const k in player) {
        if (/caption|subtitle|track/i.test(k)) {
          props.push(k);
        }
      }
      logs.push('Player caption props: ' + props.join(', '));

      // 尝试获取 tracklist
      try {
        const list = player.getCaptionTrackList();
        logs.push('Tracklist: ' + JSON.stringify(list));
      } catch (e) {
        logs.push('getCaptionTrackList err: ' + e.message);
      }

      // 设置为 en 音轨并开启
      try {
        player.loadModule('captions');
        player.setOption('captions', 'track', { languageCode: 'en' });
        player.setOption('captions', 'reload', true);
        logs.push('Set caption to en success');
      } catch (e) {
        logs.push('Set caption err: ' + e.message);
      }
    }

    return { logs };
  });

  console.log('Player evaluation logs:', playerResult.logs);

  // 等待 5 秒观察网络捕获
  await new Promise(r => setTimeout(r, 5000));

  const captured = await page.evaluate(() => window.__capturedTimedtext);
  console.log('Captured timedtext requests in MAIN world:');
  console.log(JSON.stringify(captured, null, 2));

  await browser.close();
}

testMainWorld().catch(console.error);

