async function checkTranscript() {
  const edgePath = 'C:\\Program Files (x86)\\Microsoft\\Edge\\Application\\msedge.exe';
  const targetUrl = 'https://www.youtube.com/watch?v=XHI2asm60G4&t=3736s';

  const browser = await puppeteer.launch({
    executablePath: edgePath,
    headless: false,
    args: ['--no-sandbox', '--window-size=1280,850']
  });

  const page = (await browser.pages())[0];
  await page.goto(targetUrl, { waitUntil: 'domcontentloaded' });
  await new Promise(r => setTimeout(r, 4000));

  // 检查页面上是否有 transcript 按钮
  const res = await page.evaluate(async () => {
    // 展开视频简介
    const expandBtn = document.querySelector('#expand, #description-inline-expander');
    if (expandBtn) expandBtn.click();

    await new Promise(r => setTimeout(r, 1500));

    // 寻找转录文稿按钮
    const allButtons = Array.from(document.querySelectorAll('button, ytd-button-renderer'));
    const transcriptBtn = allButtons.find(b => 
      b.textContent?.includes('文字记录') || 
      b.textContent?.includes('转录') || 
      b.textContent?.includes('Transcript') ||
      b.textContent?.includes('文字起こし')
    );

    let hasTranscriptBtn = !!transcriptBtn;
    if (transcriptBtn) {
      transcriptBtn.click();
    }

    return {
      hasTranscriptBtn,
      btnText: transcriptBtn?.textContent?.trim() || null
    };
  });

  console.log('Transcript button check:', res);
  await new Promise(r => setTimeout(r, 3000));

  // 检查是否弹出了转录侧边栏
  const transcriptSegments = await page.evaluate(() => {
    const items = document.querySelectorAll('ytd-transcript-segment-renderer');
    return {
      count: items.length,
      sample: Array.from(items).slice(0, 5).map(el => ({
        time: el.querySelector('.segment-timestamp')?.textContent?.trim(),
        text: el.querySelector('.segment-text')?.textContent?.trim()
      }))
    };
  });

  console.log('Transcript segments found:', transcriptSegments);
  await page.screenshot({ path: 'transcript-check.png' });

  await browser.close();
}

