import puppeteer from 'puppeteer-core';
import path from 'path';
import fs from 'fs';
import os from 'os';

async function verifyFinal() {
  const extensionPath = path.resolve('.output/chrome-mv3');
  const edgePath = 'C:\\Program Files (x86)\\Microsoft\\Edge\\Application\\msedge.exe';
  const targetUrl = 'https://www.youtube.com/watch?v=XHI2asm60G4&t=3736s';
  const testUserDataDir = path.join(os.tmpdir(), 'edge-final-' + Date.now());

  console.log('Launching Edge for final verification...');
  const browser = await puppeteer.launch({
    executablePath: edgePath,
    headless: false,
    userDataDir: testUserDataDir,
    args: [
      `--disable-extensions-except=${extensionPath}`,
      `--load-extension=${extensionPath}`,
      '--no-sandbox',
      '--window-size=1280,850'
    ]
  });

  const page = (await browser.pages())[0] || await browser.newPage();
  await page.setViewport({ width: 1280, height: 850 });

  page.on('console', (msg) => {
    const text = msg.text();
    if (text.includes('YT-Sub')) {
      console.log(`[Browser Console] ${text}`);
    }
  });

  console.log('Navigating to target video:', targetUrl);
  await page.goto(targetUrl, { waitUntil: 'domcontentloaded' });
  await new Promise(r => setTimeout(r, 6000));

  // 点击控制栏上的快捷按钮
  console.log('Clicking control bar button...');
  await page.evaluate(() => {
    const btn = document.querySelector('.yt-sub-translator-cbar-btn');
    if (btn) btn.click();
  });

  await new Promise(r => setTimeout(r, 1200));

  // 截取快捷面板与控制栏状态
  await page.screenshot({ path: 'verification-final.png' });
  console.log('Saved verification-final.png');

  // 获取状态面板中的文字
  const statusInfo = await page.evaluate(() => {
    const host = document.getElementById('yt-sub-translator-host');
    const statusText = host?.shadowRoot?.getElementById('qp-track-status')?.textContent;
    const badgeText = host?.shadowRoot?.querySelector('.status-indicator')?.textContent;
    return { statusText, badgeText };
  });
  console.log('Status Info:', statusInfo);

  await browser.close();
  try {
    fs.rmSync(testUserDataDir, { recursive: true, force: true });
  } catch (e) {}

  console.log('Final verification done.');
}

verifyFinal().catch(console.error);

import fs from 'fs';
import readline from 'readline';
import path from 'path';

async function parseTranscript() {
  const transcriptPath = 'C:\\Users\\ASUS\\.gemini\\antigravity\\brain\\e1d767d1-e0c6-46d5-8856-e837f406f4c9\\.system_generated\\logs\\transcript_full.jsonl';
  const outDir = 'C:\\Users\\ASUS\\.gemini\\antigravity\\scratch\\yt-sub-translator\\docs\\conversations';

  if (!fs.existsSync(outDir)) {
    fs.mkdirSync(outDir, { recursive: true });
  }

  const fileStream = fs.createReadStream(transcriptPath);
  const rl = readline.createInterface({
    input: fileStream,
    crlfDelay: Infinity
  });

  const turns = [];
  let currentTurn = null;

  for await (const line of rl) {
    if (!line.trim()) continue;
    try {
      const obj = JSON.parse(line);
      if (obj.type === 'USER_INPUT') {
        const text = typeof obj.content === 'string' ? obj.content : JSON.stringify(obj.content);
        // 过滤系统注入的自动唤醒消息
        if (!text.includes('<SYSTEM_MESSAGE>')) {
          if (currentTurn) {
            turns.push(currentTurn);
          }
          currentTurn = {
            step_index: obj.step_index,
            created_at: obj.created_at,
            user: text.replace(/<USER_REQUEST>/g, '').replace(/<\/USER_REQUEST>/g, '').trim(),
            assistant: ''
          };
        }
      } else if (obj.type === 'PLANNER_RESPONSE' && currentTurn) {
        if (typeof obj.content === 'string' && obj.content.trim()) {
          // 只保留模型输出给用户的文字内容
          currentTurn.assistant = obj.content.trim();
        }
      }
    } catch (e) {}
  }

  if (currentTurn) {
    turns.push(currentTurn);
  }

  console.log(`Parsed ${turns.length} user-assistant conversation turns.`);

  // 生成排版良好的 Markdown
  let md = `# YouTube 智能双语断句与翻译扩展 - 开发对话全量归档\n\n`;
  md += `> 本文档自动归档了本项目从零构建、功能迭代、问题排查到真实浏览器验证的全部开发对话与技术决策记录。\n`;
  md += `> 归档时间：${new Date().toLocaleString('zh-CN')}\n\n---\n\n`;

  turns.forEach((turn, idx) => {
    md += `## 轮次 ${idx + 1} (${turn.created_at || '时间未记录'})\n\n`;
    md += `### 👤 用户需求\n\n`;
    md += `\`\`\`text\n${turn.user}\n\`\`\`\n\n`;
    md += `### 🤖 Antigravity 响应与实现方案\n\n`;
    md += `${turn.assistant || '（该轮次主要执行自动化任务与工具调用）'}\n\n`;
    md += `---\n\n`;
  });

  const mdPath = path.join(outDir, 'CONVERSATION_HISTORY.md');
  fs.writeFileSync(mdPath, md, 'utf-8');
  console.log(`Saved Markdown to: ${mdPath}`);

  // 同时将原始 jsonl 复制过去一份
  fs.copyFileSync(
    transcriptPath,
    path.join(outDir, 'transcript_raw.jsonl')
  );
  console.log(`Saved raw transcript to: ${path.join(outDir, 'transcript_raw.jsonl')}`);
}

parseTranscript().catch(console.error);

