          currentTurn.assistant = obj.content.trim();
        }
      }
    } catch (e) {}
  }

  if (currentTurn) {
    turns.push(currentTurn);
  }

  let md = `# YouTube 智能双语断句与翻译扩展 - 开发对话与技术决策全量归档\n\n`;
