  md += `> 同步时间：${new Date().toLocaleString('zh-CN')}\n\n---\n\n`;

  turns.forEach((turn, idx) => {
    md += `## 轮次 ${idx + 1} (${turn.created_at || '时间未记录'})\n\n`;
    md += `### 👤 用户需求 / 输入\n\n`;
    md += `\`\`\`text\n${turn.user}\n\`\`\`\n\n`;
    md += `### 🤖 Antigravity 响应与实现方案\n\n`;
